import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.Cr9EE2ob.js";const g=JSON.parse('{"title":"Deployment","description":"Deployment topology, sizing, and high availability. This is a design-level reference; for step-by-step setup see the Installation Guide.","frontmatter":{"outline":[2,4],"head":[["meta",{"name":"robots","content":"noindex"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/installation/deployment.html"}],["meta",{"property":"og:title","content":"Deployment"}],["meta",{"name":"twitter:title","content":"Deployment"}],["meta",{"property":"og:description","content":"Deployment topology, sizing, and high availability. This is a design-level reference; for step-by-step setup see the Installation Guide."}],["meta",{"name":"twitter:description","content":"Deployment topology, sizing, and high availability. This is a design-level reference; for step-by-step setup see the Installation Guide."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/installation/deployment.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/installation/deployment.html\\",\\"headline\\":\\"Deployment\\",\\"description\\":\\"Deployment topology, sizing, and high availability. This is a design-level reference; for step-by-step setup see the Installation Guide.\\",\\"dateModified\\":\\"2026-10-22T19:56:45.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Deployment\\",\\"item\\":\\"https://doc.yarilomail.org/main/installation/deployment.html\\"}]}]}"]]},"headers":[],"relativePath":"installation/deployment.md","filePath":"installation/deployment.md","lastUpdated":1792699005000}'),i={name:"installation/deployment.md"};function n(r,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h1><p>Deployment topology, sizing, and high availability. This is a design-level reference; for step-by-step setup see the <a href="/main/installation/">Installation Guide</a>.</p><h2 id="architecture-model" tabindex="-1">Architecture model <a class="header-anchor" href="#architecture-model" aria-label="Permalink to &quot;Architecture model&quot;">​</a></h2><p>yarilo is a Go application that uses <strong>goroutines</strong> for concurrency, not a process per user as the reference does. A single process (e.g. <code>yarilo-imap</code>) serves N user sessions through goroutines (~100 KB per session).</p><p><strong>Multi-binary, multi-process:</strong></p><ul><li>6 binaries in the session role: <code>yarilo-imap</code>, <code>yarilo-pop3</code>, <code>yarilo-submission</code>, <code>yarilo-lmtp</code>, <code>yarilo-managesieve</code>, <code>yarilo-jmap</code></li><li>6 login proxies in front of them: <code>yarilo-imap-login</code>, <code>yarilo-pop3-login</code>, <code>yarilo-submission-login</code>, <code>yarilo-lmtp-login</code>, <code>yarilo-managesieve-login</code>, <code>yarilo-jmap-login</code>, plus <code>yarilo-sasl-login</code> for a fronting MTA</li><li><code>yarilo-director</code> decides which backend serves each user; it carries no client traffic</li><li>Each is a distinct process with its own address space</li><li>Coordination between session processes within a backend deployment goes through <code>yarilo-locks</code></li></ul><p>Goroutines vs fork:</p><ul><li>1000 users in a single pod ≈ 200–500 MB RAM, not 10 GB</li><li>No &quot;fat pod&quot; problem</li><li>Horizontal scaling is for HA, not for resource limits</li></ul><hr><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="login-proxies-and-the-director" tabindex="-1">login proxies and the director <a class="header-anchor" href="#login-proxies-and-the-director" aria-label="Permalink to &quot;login proxies and the director&quot;">​</a></h3><p>The login proxies (<code>yarilo-imap-login</code>, <code>yarilo-pop3-login</code>, <code>yarilo-submission-login</code>, <code>yarilo-lmtp-login</code>, <code>yarilo-managesieve-login</code>, <code>yarilo-jmap-login</code>) are separate Deployments. This is where <strong>TLS terminate + passdb auth + allow_nets enforcement</strong> happens.</p><p><code>yarilo-director</code> is its own Deployment: replicas form a self-organizing ring and answer each login proxy&#39;s <code>LOOKUP</code> with the user&#39;s backend, through a <strong>consistent-hashing ring</strong> plus sticky assignments. See <a href="/main/architecture/director.html">Director</a>.</p><p><code>yarilo-jmap-login</code> carries the same duties over HTTP; the flow below describes the byte-pipe protocols, and <a href="#jmap-frontend-and-backend">JMAP — the HTTP frontend/backend split</a> describes where it differs.</p><p><strong>Login pod auth flow:</strong></p><ol><li>Accept TLS connection from client.</li><li>Extract real client IP from HAProxy PROXY protocol header or raw TCP RemoteAddr.</li><li>Parse the IMAP/POP3/SMTP AUTHENTICATE or LOGIN command to obtain credentials.</li><li>Call <strong>yarilo-auth</strong> (<code>AUTH</code> command) — passdb chain runs there; receives <code>token=</code> on success. <code>allow_<wbr>nets</code> and <code>nologin</code> are enforced in the login pod using the real client IP.</li><li>On failure: send <code>NO Invalid credentials</code> to the client. Backend is never contacted.</li><li>On success: send proto-specific auth OK to the client, then dial the backend and send:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>YARILO\\tADDR=&lt;real-client-ip&gt;\\tSESSION=&lt;warden-id&gt;\\tUSER=&lt;username&gt;\\tTOKEN=&lt;64hex&gt;\\n</span></span></code></pre></div></li><li>Backend reads the preamble, calls yarilo-auth <code>VERIFY token</code> to confirm the session, and enters pre-authenticated state. No passdb round-trip on the backend side.</li></ol><h3 id="backend-deployment-one-per-tag-one-per-nfs-shard" tabindex="-1">backend deployment (one per tag = one per NFS shard) <a class="header-anchor" href="#backend-deployment-one-per-tag-one-per-nfs-shard" aria-label="Permalink to &quot;backend deployment (one per tag = one per NFS shard)&quot;">​</a></h3><p>Handles authenticated mail sessions, reading and writing mail + index data to NFS.</p><p><strong>Co-located pod (one pod serves ALL of a user&#39;s per-user state).</strong> A backend pod is a <strong>single StatefulSet</strong> whose pod runs one container per protocol — <code>yarilo-imap</code>, <code>yarilo-pop3</code>, <code>yarilo-submission</code>, <code>yarilo-lmtp</code>, <code>yarilo-managesieve</code>, <code>yarilo-jmap</code> — plus the <code>yarilo-fts</code> full-text-search container, the <code>yarilo-backend-api</code> admin container, and a <code>yarilo-backend-reg</code> registration sidecar, sharing the pod&#39;s <strong>one IP</strong> and the tag&#39;s <strong>one NFS PV (RWX)</strong>. <code>yarilo-locks</code> runs as its own per-tag Deployment for cross-pod write coordination.</p><p><strong>What goes in the pod vs stays separate — the criterion.</strong> The pod holds everything that owns <strong>per-user write state</strong>: the protocol containers, <code>fts</code> (per-user Xapian index), and <code>backend-api</code> (its <code>fts rescan</code>/<code>optimize</code> and direct mailbox/index access write a user&#39;s data — as a standalone Deployment it would be a <em>second</em> writer of the same index/mailbox the user&#39;s sticky pod owns; in-pod it uses that pod&#39;s localhost fts, so single-writer holds). <code>backend-api</code> listens on the <strong>pod IP only</strong>; <code>yarctl</code> reaches the owning pod by doing a director LOOKUP itself and dialing that pod. <strong>Global-read services with stable external consumers stay separate</strong> — <code>yarilo-quota-status</code> is a Postfix policy service the external MTA dials at a fixed endpoint, and it only reads a shared quota dict (any instance answers any user, no per-user write), so co-locating it would break the MTA contract for zero gain. It stays its own Deployment.</p><p>This is deliberate and load-bearing for the whole director model: it restores the reference&#39;s invariant <strong>one mail-host owns every per-user resource</strong>. Because the pod at a given IP answers imap <em>and</em> pop3 <em>and</em> lmtp <em>and</em> submission <em>and</em> managesieve, the director needs only <strong>one ring and one user→pod map</strong> — a user hashes to one pod IP, and that IP is correct for every protocol (the login proxy dials the protocol-specific port on that same IP). See &quot;Director routing&quot; and &quot;Why co-located, not per-protocol StatefulSets&quot; below.</p><p><strong>FTS is co-located for the same reason.</strong> The Xapian index is <strong>per-user</strong>, and a session reaches FTS over <code>ftsproto</code>. With a shared ClusterIP as <code>fts.<wbr>fts_<wbr>addr</code>, requests for one user&#39;s index round-robin across <code>yarilo-fts</code> replicas → two pods cache the same user&#39;s write handle → corruption (which is why <code>replicas &gt; 1</code> used to be unsafe). The chart therefore runs <code>yarilo-fts</code> in the pod and renders <code>fts_<wbr>addr</code> as <code>localhost:&lt;port&gt;</code>, which makes the user&#39;s <strong>already-sticky</strong> pod the sole owner of that user&#39;s index write handle. On the shared NFS every per-user Xapian dir then has exactly one writer — the same &quot;1 user = 1 pod&quot; invariant that keeps a mailbox on one pod gives FTS single-writer for free, so <code>replicas &gt; N</code> is safe (indexing load follows the users on each pod).</p><p>Declare the storage in the chart: <code>fts.<wbr>fts_<wbr>storage_<wbr>type: &quot;nfs&quot;</code> for every backend tag (the shards live on the tag&#39;s RWX PV), <code>&quot;local&quot;</code> for a standalone on a local PV. It is a declaration, not a detection, and it decides where a durability call is real — see the setting&#39;s own note in <code>helm/<wbr>values.<wbr>yaml</code>.</p><div class="warning custom-block"><p class="custom-block-title">The NFS export must be <code>sync</code></p><p>This is a server setting no code path can compensate for. NFSv3/v4 require metadata operations (<code>RENAME</code>, <code>REMOVE</code>, <code>RMDIR</code>) to be committed to stable storage before the reply, and every atomic write in yarilo — index and cache tmp+rename, maildir delivery, FTS shard compaction — rests on that. An <code>async</code> export answers before committing, so a crash can lose a rename the client was told had succeeded; a client-side <code>fsync</code> cannot repair it (there is no commit-a-directory operation, and <code>fsync</code> on a directory is a no-op over NFS). The cost of <code>async</code> is paid in silently rolled-back metadata, not in a visible error.</p></div><p><strong>Login proxies are not needed inside the backend</strong> — it accepts plain TCP from the login pods with auth state in the YARILO preamble. The login pods (<code>yarilo-imap-login</code>, …, <code>yarilo-sasl-login</code>) are their own Deployments (see <code>/<wbr>yarilo_<wbr>director.<wbr>svg</code>), never here.</p><p>Backend auth logic:</p><ul><li>Login pod sends <code>YARILO\\tADDR=.<wbr>.<wbr>.<wbr>\\tSESSION=.<wbr>.<wbr>.<wbr>\\tUSER=.<wbr>.<wbr>.<wbr>\\tTOKEN=.<wbr>.<wbr>.<wbr>\\n</code> before any protocol exchange.</li><li>Backend&#39;s <code>PreambleListener</code> reads the preamble, calls yarilo-auth VERIFY (<code>service=</code> field enforced), enters pre-authenticated state.</li><li>Every backend protocol container accepts only the YARILO preamble from login pods (director is control-plane only — it never touches client bytes). Client-IP forwarding into the <em>login</em> layer, when needed, is haproxy protocol / native inbound (ID/XCLIENT) / none, chosen per protocol — it never reaches the backend directly. LMTP preamble originates from <code>yarilo-lmtp-login</code>.</li></ul><h3 id="upgrading-the-backend-statefulset" tabindex="-1">Upgrading the backend StatefulSet <a class="header-anchor" href="#upgrading-the-backend-statefulset" aria-label="Permalink to &quot;Upgrading the backend StatefulSet&quot;">​</a></h3><p>A backend pod is replaced in place: the StatefulSet stops the old pod first and only then creates the new one, one pod at a time. The tag runs one backend short until the new pod is Ready, and that time includes the image pull and the scheduling. On the sandbox (<code>assignment_<wbr>policy: domain</code>) a slow pull kept one backend down for about 4.5 minutes, its users without service, and with CPU requests at 92 % of the node the new pod stayed <code>Pending</code> until other old pods left. Before <code>helm upgrade</code> in production, pull the new image on every node that runs backend pods (for example <code>crictl pull docker.<wbr>io/<wbr>0kaba0/<wbr>yarilo:&lt;tag&gt;</code>), and keep free CPU and memory on those nodes for the requests of one more backend pod.</p><h3 id="backend-registration-and-heartbeat" tabindex="-1">Backend registration and heartbeat <a class="header-anchor" href="#backend-registration-and-heartbeat" aria-label="Permalink to &quot;Backend registration and heartbeat&quot;">​</a></h3><p>Backends are registered in the director ring by <strong>self-registration + heartbeat</strong>, not by a one-time DNS resolve or an external prober. This makes the backend list a second application of the exact lifecycle machinery already built for the director ring itself (JOIN on start, ring-wide keepalive, graceful leave, Lamport ordering, tombstone-free convergence) rather than a separate DNS-poll mechanism — and it works in <strong>every</strong> topology (k8s and non-k8s standalone), consistent with config-not-binary.</p><p><strong>One registration per POD, not per protocol.</strong> Because the pod is co-located, exactly <strong>one</strong> <code>yarilo-backend-reg</code> sidecar per pod owns the director registration — it registers the <strong>pod IP once</strong>, not one stream per protocol container. This is not cosmetic: four protocol containers each registering the same IP would push four independent monotonic-seq streams for one origin, and the strictly-newer lease dedup compares seq only within an origin — four interleaved streams on one IP would fight, each rejecting the others as stale. One sidecar = one origin = one clean seq stream. The sidecar reuses the exact <code>internal/<wbr>backendreg</code> client, which answers the director&#39;s PING with PONG and resets its reconnect backoff on a healthy long-lived connection; without those a co-located pod would flap <strong>as a whole</strong>.</p><p>Model:</p><ul><li><strong>Register on start.</strong> The <code>yarilo-backend-reg</code> sidecar dials the director <strong>ClusterIP Service</strong> — it does not matter which director replica answers; a load-balanced address is correct here precisely because the registration is gossiped <strong>ring-wide</strong>. It sends <code>BACKEND-UP\\t{ip}\\t{port}\\t{tag}\\t{vhosts}\\t{seq}</code> for the <strong>pod IP</strong>; the receiving director adds it and forwards it as a <code>RING-CHANGE up</code> envelope (carrying port + vhosts) so every director learns it. <code>{port}</code> is nominal — login proxies override it with their own protocol port (<code>internal/<wbr>login</code> BackendPort / lmtp-login BackendPort), dialing <code>{pod-ip}:{protocol-port}</code>; the ring entry identifies the POD, the login picks the protocol port. (This is the only backend→director control channel — otherwise the director only ever dials backends.)</li><li><strong><code>{tag}</code> is the STORAGE SHARD, never the protocol.</strong> A co-located pod serves all protocols, so protocol is not a routing dimension — the tag stays a pure NFS-shard label (one tag = one NFS PV = one <code>yarilo-backend</code> release). Per-user shard selection (userdb <code>director_<wbr>tag</code>) is unaffected.</li><li><strong>Heartbeat = periodic re-register, gated on the PROTOCOL containers&#39; self-health.</strong> Every <code>register_<wbr>interval</code> seconds (Helm: <code>backend_<wbr>register.<wbr>register_<wbr>interval</code>) the sidecar re-sends <code>BACKEND-UP</code> — but ONLY while <strong>every protocol</strong> container in the pod is serving (each protocol&#39;s <code>/<wbr>readyz</code>: listener accepting and not wedged). A heartbeat must prove the DATA PATH is alive, not merely that a control goroutine still ticks. <strong>Readiness-gate semantics (spell this out for operators):</strong> because it is one pod = one ring entry, a <em>single</em> unready protocol container makes the whole pod go silent → the lease expires → the pod is removed for <strong>all</strong> protocols. This is correct and matches the reference (host down = down for everything on that host), but it is a real coupling: an NFS-wedged <code>yarilo-lmtp</code> will pull the pod&#39;s IMAP traffic off too. That is the price of the one-mail-host invariant, and the sidecar&#39;s gate makes the wedge fail safe (silence → expiry) rather than routing to a half-dead pod. <strong><code>yarilo-fts</code> is deliberately NOT in the gate:</strong> FTS is best-effort (a wedged index degrades SEARCH to a slow fallback but never blocks mail flow), so an unhealthy fts container must not evict the pod&#39;s live IMAP/LMTP traffic. Each heartbeat carries a <strong>monotonic per-origin sequence</strong> (a logical counter, NOT wall-clock — pod clocks are unsynchronized, so freshness is compared only <em>within</em> one backend&#39;s own origin; the seq is seeded from the process start time so a same-IP restart resumes above the director&#39;s last-recorded seq), gossiped ring-wide as &quot;backend X seen at seq N&quot;. Every director keeps the max seen per backend; a heartbeat landing on <strong>any</strong> director refreshes the lease everywhere — this is what makes a load-balanced heartbeat correct (a per-director timer with LB&#39;d heartbeats would false-expire a live backend on the directors that happened not to receive it).</li><li><strong>TTL expiry → LEAVE (remove + rehash).</strong> A backend whose last-seen has not advanced within <code>backend_<wbr>expire</code> on the ring is REMOVED (<code>RING-CHANGE down</code> → <code>RemoveBackend</code> everywhere); its hash-slice rehashes onto neighbouring backends in the same tag. This covers the silent hang / crash with no external prober.</li><li><strong>Graceful leave → LEAVE (remove + rehash).</strong> On SIGTERM the backend sends <code>BACKEND-DOWN</code> (like the director&#39;s own graceful leave) so it is removed immediately without waiting out the TTL — a planned rollout / scale-down never blackholes a hash-slice for the expiry window.</li><li><strong>A removed backend stays removed.</strong> Removal drops the users and domains placed on it, as well as its ring entry. A peer&#39;s ring handshake, an anti-entropy snapshot, a late heartbeat or a gossiped placement naming it is ignored; only a registration newer than the removal brings the address back, as a pod restarted on it does. The block lasts 5 minutes plus <code>backend_<wbr>expire</code>, the longest another director can keep the backend after its last heartbeat. A backend learned from a handshake carries its lease, so it expires like any other when its heartbeats stop.</li><li><strong>Overload → FLUSH (drain, NO rehash), never DOWN.</strong> Removal and overload are DIFFERENT wire events with different consequences and must not be conflated. A backend shedding load sends <code>BACKEND-FLUSH</code>: it STAYS in the ring, new LOOKUPs stop landing on it, existing sessions keep running — its hash-slice does NOT move. A transient load spike therefore causes zero user reshuffling. Sending <code>BACKEND-DOWN</code> on overload would remove it → rehash the slice away → and then a second rehash back when it re-registers a minute later: double-shuffling users through a transient peak, worse than the peak itself. This matches the reference&#39;s down/vhosts semantics (drain by zeroing vhosts, not by removal). <code>BACKEND-DOWN</code> is reserved for genuine LEAVE (SIGTERM / expiry).</li></ul><p>Safety + migration:</p><ul><li><strong>Never remove the last backend of a tag</strong> by TTL expiry — a suspect-but-only backend is kept (and logged loudly) rather than guaranteeing a total blackhole for that tag.</li><li><strong>Static <code>mail_<wbr>servers</code> entries stay non-expiring</strong> — they are a bootstrap / non-k8s fallback and are never pruned by the heartbeat lease, so registration can be rolled out incrementally with no binary branching (config-not-binary).</li><li><strong>admin-API <code>backends add/<wbr>remove</code> stay manual and non-expiring</strong> — an operator&#39;s explicit entry is never touched by the lease.</li><li><strong>No tombstone needed</strong> (unlike ring members whose ephemeral pod identity never returns): a dead backend heartbeats nowhere and never re-registers, so a gossiped ghost simply ages out at TTL.</li></ul><p>One <code>backend_<wbr>register</code> block per pod drives the single <code>yarilo-backend-reg</code> sidecar; there is <strong>no</strong> per-protocol registration path.</p><h4 id="director_service.backend_expire" tabindex="-1"><code>backend_<wbr>expire</code> <a class="header-anchor" href="#director_service.backend_expire" aria-label="Permalink to &quot;`backend_expire` {#director_service.backend_expire}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>30</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.backend_expire</code></dd><dt>See also</dt><dd><a href="/main/installation/deployment.html#backend_register.register_interval"><code>register_interval</code></a></dd></dl></div><p>Missed heartbeats for this long remove a backend from the ring on every director, and its users are rehashed onto the other backends of its tag.</p><h4 id="backend_register.director_addr" tabindex="-1"><code>director_<wbr>addr</code> <a class="header-anchor" href="#backend_register.director_addr" aria-label="Permalink to &quot;`director_addr` {#backend_register.director_addr}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>backend_register.director_addr</code></dd></dl></div><p>The director Service the registration sidecar sends <code>BACKEND-UP</code> to. Any replica may answer: the registration is spread around the ring.</p><h4 id="backend_register.register_interval" tabindex="-1"><code>register_<wbr>interval</code> <a class="header-anchor" href="#backend_register.register_interval" aria-label="Permalink to &quot;`register_interval` {#backend_register.register_interval}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>10</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>backend_register.register_interval</code></dd><dt>See also</dt><dd><a href="/main/installation/deployment.html#director_service.backend_expire"><code>backend_expire</code></a></dd></dl></div><p>How often the sidecar re-registers the pod. It sends only while every protocol container of the pod is ready, so a wedged container lets the lease run out.</p><h4 id="backend_register.tag" tabindex="-1"><code>tag</code> <a class="header-anchor" href="#backend_register.tag" aria-label="Permalink to &quot;`tag` {#backend_register.tag}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>backend_register.tag</code></dd></dl></div><p>The storage shard this pod serves: one tag is one NFS volume and one backend release. It is never the protocol; a pod serves every protocol.</p><h4 id="backend_register.vhosts" tabindex="-1"><code>vhosts</code> <a class="header-anchor" href="#backend_register.vhosts" aria-label="Permalink to &quot;`vhosts` {#backend_register.vhosts}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>100</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>backend_register.vhosts</code></dd><dt>See also</dt><dd><a href="/main/installation/deployment.html#director_service.assignment_policy"><code>assignment_policy</code></a></dd></dl></div><p>The pod&#39;s weight on the ring, from <code>1</code> to <code>100</code>. Under <code>assignment_<wbr>policy: least_<wbr>sessions</code>, <code>0</code> drains the backend: it takes no new users.</p><h3 id="backend-watchdog-probe" tabindex="-1">Backend watchdog probe <a class="header-anchor" href="#backend-watchdog-probe" aria-label="Permalink to &quot;Backend watchdog probe&quot;">​</a></h3><p>Distinct from ring registration above: that governs whether a backend is a routing target, this governs whether a wedged container is <strong>restarted</strong>.</p><p>The three probes on each co-located protocol container answer three different questions, and only one of them can restart the container:</p><ul><li><strong>startupProbe</strong> — dependencies (locks, Redis, DB) are reachable before the container takes traffic. Runs once at start.</li><li><strong>readinessProbe</strong> — the pod&#39;s per-protocol freshness file is fresh, so the login proxy only routes to a container that is currently serving. Removes from endpoints, never restarts.</li><li><strong>livenessProbe</strong> — <code>/<wbr>healthz</code>, which is unconditional until the <strong>liveness watchdog</strong> trips it. The watchdog is a timer-driven self-check (stat the mail store base, enter a local gate) that fails <code>/<wbr>healthz</code> when the request path is wedged in a way nothing else sees: a stale NFS handle hanging every mailbox op, or an in-process deadlock, while the accept loop and this HTTP server keep answering. Restarting is then the only correct response, and liveness is the only probe that restarts.</li></ul><p><strong>Why liveness is gated on the watchdog.</strong> Without a self-check, <code>/<wbr>healthz</code> answers 200 as long as the telemetry server runs, so a liveness probe on it is inert — it can only ever catch the telemetry server itself dying, which the process&#39;s own <code>os.<wbr>Exit(1)</code> on a dead accept loop already covers. So the backend carried no livenessProbe historically. The probe is therefore rendered <strong>only when <code>telemetry.<wbr>livenessWatchdog.<wbr>enabled</code></strong> is set: enabling the watchdog is what makes <code>/<wbr>healthz</code> a real signal, and only then does watching it with a restart make sense. Off by default preserves the prior no-restart behaviour exactly.</p><p><strong>Guard rails against restarting a healthy busy pod:</strong> the watchdog trips only after several consecutive failed self-checks, the self-check timeout is shorter than its interval, the probe has its own <code>failureThreshold</code> on top, and the self-check touches <strong>nothing shared</strong> — so a hung NFS handle restarts the one pod that mounts it, and a database hiccup restarts nothing. A single protocol container restarts alone; the other protocols on the pod keep serving.</p><h4 id="telemetry.liveness_watchdog.liveness_watchdog_enabled" tabindex="-1"><code>liveness_<wbr>watchdog_<wbr>enabled</code> <a class="header-anchor" href="#telemetry.liveness_watchdog.liveness_watchdog_enabled" aria-label="Permalink to &quot;`liveness_watchdog_enabled` {#telemetry.liveness_watchdog.liveness_watchdog_enabled}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>telemetry.livenessWatchdog.enabled</code></dd></dl></div><p>Restart a container whose request path is wedged (a deadlock, a hung NFS handle) while the process still answers. The self-check touches nothing shared, so a database hiccup restarts nothing.</p><h4 id="telemetry.liveness_watchdog.liveness_watchdog_interval_seconds" tabindex="-1"><code>liveness_<wbr>watchdog_<wbr>interval_<wbr>seconds</code> <a class="header-anchor" href="#telemetry.liveness_watchdog.liveness_watchdog_interval_seconds" aria-label="Permalink to &quot;`liveness_watchdog_interval_seconds` {#telemetry.liveness_watchdog.liveness_watchdog_interval_seconds}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>10</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>telemetry.livenessWatchdog.intervalSeconds</code></dd></dl></div><p>How often the self-check runs.</p><h4 id="telemetry.liveness_watchdog.liveness_watchdog_timeout_seconds" tabindex="-1"><code>liveness_<wbr>watchdog_<wbr>timeout_<wbr>seconds</code> <a class="header-anchor" href="#telemetry.liveness_watchdog.liveness_watchdog_timeout_seconds" aria-label="Permalink to &quot;`liveness_watchdog_timeout_seconds` {#telemetry.liveness_watchdog.liveness_watchdog_timeout_seconds}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>5</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>telemetry.livenessWatchdog.timeoutSeconds</code></dd></dl></div><p>How long one self-check may take before it counts as failed.</p><h4 id="telemetry.liveness_watchdog.liveness_watchdog_failure_threshold" tabindex="-1"><code>liveness_<wbr>watchdog_<wbr>failure_<wbr>threshold</code> <a class="header-anchor" href="#telemetry.liveness_watchdog.liveness_watchdog_failure_threshold" aria-label="Permalink to &quot;`liveness_watchdog_failure_threshold` {#telemetry.liveness_watchdog.liveness_watchdog_failure_threshold}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>3</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>telemetry.livenessWatchdog.failureThreshold</code></dd></dl></div><p>Failed self-checks in a row before the liveness probe fails.</p><h4 id="telemetry.liveness_watchdog.liveness_watchdog_fault_injection_enabled" tabindex="-1"><code>liveness_<wbr>watchdog_<wbr>fault_<wbr>injection_<wbr>enabled</code> <a class="header-anchor" href="#telemetry.liveness_watchdog.liveness_watchdog_fault_injection_enabled" aria-label="Permalink to &quot;`liveness_watchdog_fault_injection_enabled` {#telemetry.liveness_watchdog.liveness_watchdog_fault_injection_enabled}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>telemetry.livenessWatchdog.faultInjectionEnabled</code></dd></dl><p class="setting-advanced">Advanced: this should not normally be changed.</p></div><p>Expose <code>POST /<wbr>debug/<wbr>fault/<wbr>deadlock</code>, which wedges the self-check so you can confirm on a live pod that the watchdog restarts it. Leave it off outside such a check.</p><h3 id="profiling-a-live-pod" tabindex="-1">Profiling a live pod <a class="header-anchor" href="#profiling-a-live-pod" aria-label="Permalink to &quot;Profiling a live pod&quot;">​</a></h3><p>The Go runtime profilers are served on the telemetry port, and are <strong>off by default</strong>. They answer questions no metric can: which function a saturated worker is actually in, where a component&#39;s allocations come from, and why adding CPU makes a stage slower rather than faster.</p><p>One switch turns them on:</p><h4 id="telemetry.telemetry_pprof_enabled" tabindex="-1"><code>telemetry_<wbr>pprof_<wbr>enabled</code> <a class="header-anchor" href="#telemetry.telemetry_pprof_enabled" aria-label="Permalink to &quot;`telemetry_pprof_enabled` {#telemetry.telemetry_pprof_enabled}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>telemetry.pprof.enabled</code></dd></dl></div><p>Serve the Go profilers and <code>/<wbr>debug/<wbr>loglevel</code> on the telemetry port. Every component logs a warning at each start while it is on.</p><p>It serves:</p><ul><li><code>/<wbr>debug/<wbr>pprof/<wbr>profile</code>, <code>trace</code>, <code>allocs</code>, <code>heap</code>, <code>goroutine</code>, <code>block</code>, <code>mutex</code>, <code>threadcreate</code>, <code>cmdline</code> and <code>symbol</code>: stacks, counts and symbol names, which say what code paths the process runs and what they cost;</li><li><code>/<wbr>debug/<wbr>loglevel</code>: <code>GET</code> returns the level, and <code>POST {&quot;level&quot;:&quot;debug&quot;,&quot;ttl&quot;:&quot;10m&quot;}</code> changes it for the whole process. Off, the route answers 404.</li></ul><p><code>block</code> and <code>mutex</code> are in that list but stay silent until a sampling rate is set; see below.</p><p><strong>What a profile does not contain is the contents of anything.</strong> A pprof profile is a set of sampled stack traces with object and byte counts attached; the format has no field a message body or a credential could appear in. What it does give away is the shape of the workload — which paths run, how often, how much they allocate — and the symbol names of the binary. That is worth something to someone, which is why the switch is off by default and why every component logs a warning at each start while it is on.</p><p><code>telemetry.<wbr>pprof.<wbr>heapEnabled</code> was a second switch, on the grounds that the heap route dumped live objects while the rest were only stacks and counts. It is <strong>deprecated and does nothing</strong>; a process that finds it set says so at start. Go&#39;s <code>heap</code> and <code>allocs</code> are the same profile with different default sample types, so the allocation route always served <code>inuse_<wbr>space</code> as well — the switch withheld nothing.</p><p>Asking what is <em>retained</em> rather than what was allocated is a matter of the sample type, not the route:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pprof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -inuse_space</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/debug/pprof/allocs</span></span></code></pre></div><p>There is no <code>/<wbr>debug/<wbr>pprof/</code> index page. It dispatches any path under it to the runtime profile of that name, so the set of routes would be decided by whatever any package in the binary registered with <code>runtime/<wbr>pprof</code> rather than by the list above.</p><p>While either switch is on, every component logs a warning <strong>at every start</strong> naming what is exposed. That is deliberate — the failure this guards against is not enabling profiling, it is enabling it for an afternoon&#39;s investigation and leaving it on for a year.</p><h3 id="profiles-that-need-a-sampling-rate" tabindex="-1">Profiles that need a sampling rate <a class="header-anchor" href="#profiles-that-need-a-sampling-rate" aria-label="Permalink to &quot;Profiles that need a sampling rate&quot;">​</a></h3><p><code>/<wbr>debug/<wbr>pprof/<wbr>block</code> and <code>/<wbr>debug/<wbr>pprof/<wbr>mutex</code> are served by the switch above, but they answer with an <strong>empty profile</strong> until sampling is turned on — a diagnostic that returns 200 and says nothing. Two more values do that:</p><h4 id="telemetry.telemetry_block_profile_rate" tabindex="-1"><code>telemetry_<wbr>block_<wbr>profile_<wbr>rate</code> <a class="header-anchor" href="#telemetry.telemetry_block_profile_rate" aria-label="Permalink to &quot;`telemetry_block_profile_rate` {#telemetry.telemetry_block_profile_rate}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>telemetry.pprof.blockProfileRate</code></dd><dt>See also</dt><dd><a href="/main/installation/deployment.html#telemetry.telemetry_mutex_profile_fraction"><code>telemetry_mutex_profile_fraction</code></a></dd></dl></div><p>One sample per this many nanoseconds of blocked time; <code>0</code> is off, and <code>/<wbr>debug/<wbr>pprof/<wbr>block</code> then answers with an empty profile. Every blocking operation pays while it is on.</p><h4 id="telemetry.telemetry_mutex_profile_fraction" tabindex="-1"><code>telemetry_<wbr>mutex_<wbr>profile_<wbr>fraction</code> <a class="header-anchor" href="#telemetry.telemetry_mutex_profile_fraction" aria-label="Permalink to &quot;`telemetry_mutex_profile_fraction` {#telemetry.telemetry_mutex_profile_fraction}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>telemetry.pprof.mutexProfileFraction</code></dd><dt>See also</dt><dd><a href="/main/installation/deployment.html#telemetry.telemetry_block_profile_rate"><code>telemetry_block_profile_rate</code></a></dd></dl></div><p>One sample per this many mutex contention events; <code>0</code> is off, and <code>/<wbr>debug/<wbr>pprof/<wbr>mutex</code> then answers with an empty profile. Every contended mutex pays while it is on.</p><p>They are separate from <code>enabled</code> because serving a route and collecting samples are different costs. The route is free while nobody fetches it; the sampling is paid by <strong>every blocking operation and every contended mutex in the process</strong>, whether or not anyone ever takes the profile.</p><p>This is the instrument for time spent <em>waiting</em> — a CPU profile cannot see it, because a goroutine asleep on a lock or a socket burns nothing. Turn the rates on for the measurement window, take the capture, set them back to <code>0</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">telemetry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pprof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    blockProfileRate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # ns of blocked time per sample</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    mutexProfileFraction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # one in N contention events</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pprof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -http=:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/debug/pprof/block</span></span></code></pre></div><p>Both rates warn at every start while they are on, for the same reason the switches above do.</p><p>Taking a profile, with the telemetry port reachable only inside the cluster:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port-forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">po</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">telemetry-por</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 30 seconds of CPU, which is what identifies a hot stage</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pprof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -http=:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:8080/debug/pprof/profile?seconds=30&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># where allocations are made, and -inuse_space for what is still held</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pprof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -http=:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/debug/pprof/allocs</span></span></code></pre></div><p>The telemetry port differs per container in the co-located backend pod — each is told its own via <code>TELEMETRY_<wbr>LISTEN</code> — so take it from the container&#39;s <code>ports:</code> rather than assuming <code>8080</code>.</p><h3 id="jmap-frontend-and-backend" tabindex="-1">JMAP frontend and backend <a class="header-anchor" href="#jmap-frontend-and-backend" aria-label="Permalink to &quot;JMAP frontend and backend&quot;">​</a></h3><p>JMAP is HTTP, so the layers split the same way as every other protocol but the hop between them is <strong>per-request HTTP proxying rather than a TCP byte pipe</strong>. That is the only difference, and it is what removes the need for fd-passing: a JMAP client carries its credentials on every request, so there is no session pinned to a connection to hand over.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Duty</th><th style="text-align:left;"><code>yarilo-jmap-login</code></th><th style="text-align:left;"><code>yarilo-jmap</code></th></tr></thead><tbody><tr><td style="text-align:left;">Client TLS (<code>general.<wbr>ssl</code>), HAProxy PROXY protocol</td><td style="text-align:left;">terminates</td><td style="text-align:left;">no knowledge of client TLS</td></tr><tr><td style="text-align:left;"><code>Authorization</code> Basic/Bearer → yarilo-auth passdb chain</td><td style="text-align:left;">yes</td><td style="text-align:left;">accepts identity only from the login layer</td></tr><tr><td style="text-align:left;">warden: auth-failure penalty, per-user@IP accounting, kick bus</td><td style="text-align:left;">yes</td><td style="text-align:left;">no</td></tr><tr><td style="text-align:left;">director lookup → proxy to the user&#39;s backend pod</td><td style="text-align:left;">yes</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Storage via <code>pkg/<wbr>mailbox</code>, session object, JMAP methods</td><td style="text-align:left;">no</td><td style="text-align:left;">yes</td></tr></tbody></table><p><strong>The internal hop.</strong> After auth, <code>yarilo-jmap-login</code> resolves the user through the director and proxies the request to that pod&#39;s <code>yarilo-jmap</code> over <strong>internal mTLS</strong>, carrying <code>X-Session-ID</code>, <code>X-Proxy-TTL</code> and <code>Forwarded</code> (RFC 7239). <code>Forwarded</code> is the HTTP-native equivalent of XCLIENT, giving the backend the real client IP and TLS state for logging and warden attribution. <code>allow_<wbr>nets</code> is enforced in the login pod against the real client before proxying, as for every other protocol — one enforcement point, not two.</p><p><strong>Trust boundary.</strong> Identity travels in headers, so a request carrying <code>X-Session-ID</code> or <code>Forwarded</code> is honoured only from a peer the backend has been told to trust. Three modes, all default-deny — there is no branch in which an unknown peer is believed:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Anchor</th><th style="text-align:left;">Who may set identity headers</th></tr></thead><tbody><tr><td style="text-align:left;"><code>internal_<wbr>tls.<wbr>enabled: true</code></td><td style="text-align:left;">only the login layer&#39;s client certificate. The k8s mode.</td></tr><tr><td style="text-align:left;">mTLS off, <code>general.<wbr>xclient.<wbr>trusted_<wbr>nets</code> covers the peer</td><td style="text-align:left;">only peers inside those CIDRs. The same key that already gates XCLIENT and <code>IMAP ID x-originating-ip</code>: <code>Forwarded</code> is the HTTP member of that family, not a new concept. Enabled per listener with <code>services.<wbr>jmap.<wbr>xclient_<wbr>protocol</code>, as elsewhere.</td></tr><tr><td style="text-align:left;">neither</td><td style="text-align:left;">nobody: identity requests answer <code>403</code>, and startup logs that no trust anchor is configured.</td></tr></tbody></table><p>The third case keeps the listener up on purpose. A dead port reads as a network fault and sends the operator to the wrong place; a live port answering <code>403</code> with a named cause diagnoses itself, and <code>/<wbr>healthz</code> and <code>/<wbr>readyz</code> keep working instead of the pod entering CrashLoop.</p><p>The compose standalone has no certificate infrastructure by design — one host, a private docker network — so it adds its docker subnet to <code>general.<wbr>xclient.<wbr>trusted_<wbr>nets</code> in the shipped config. The stock default is empty, trusting no peer, so this stays an explicit entry rather than an assumption.</p><p><strong>Connection limits are warden&#39;s.</strong> Per-user and per-IP connection limits are held in warden and shared across replicas. Listeners have no <code>connection_<wbr>limit</code> key: nothing ever read it. A config that still carries one logs a retired-key warning at start.</p><p><strong>Scaling.</strong> <code>yarilo-jmap-login</code> is stateless beyond TLS and scales on request load in both shapes. <code>yarilo-jmap</code> scales differently per shape, for the same reason every other session process does: behind a director it is a container in the co-located pod and scales with it, because it reads the same per-user index and mailbox as that pod&#39;s other protocol containers and must not become a second writer of them; in the standalone shape it is its own Deployment with its own <code>replicaCount</code>, and cross-pod write contention is resolved through <code>yarilo-locks</code> like every other session Deployment there.</p><p><strong>Ports.</strong> Client-facing <code>:8443</code> on <code>yarilo-jmap-login</code>; the backend listens on <code>:10443</code>, in the same range as the other backend data ports (<code>10143</code>, <code>10110</code>, <code>10587</code>, <code>10024</code>, <code>14190</code>) and deliberately clear of <code>:8080</code>, which is the telemetry port every component pod already uses.</p><h3 id="shared-services-one-deployment-per-installation" tabindex="-1">shared services (one deployment per installation) <a class="header-anchor" href="#shared-services-one-deployment-per-installation" aria-label="Permalink to &quot;shared services (one deployment per installation)&quot;">​</a></h3><ul><li><code>yarilo-auth</code> — passdb (for the director) + userdb (for everyone)</li><li><code>yarilo-warden</code> — connection/session limits (read + write from both sides)</li></ul><h3 id="why-yarilo-locks-is-per-backend-rather-than-shared" tabindex="-1">Why <code>yarilo-locks</code> is per backend rather than shared <a class="header-anchor" href="#why-yarilo-locks-is-per-backend-rather-than-shared" aria-label="Permalink to &quot;Why `yarilo-locks` is per backend rather than shared&quot;">​</a></h3><ul><li>Each backend tag has its <strong>own NFS share</strong> — a separate data scope.</li><li>Locks apply only to files in that share; there is no reason to coordinate with other tags.</li><li>Lower latency (local to the backend pod).</li><li>Blast-radius isolation: a <code>yarilo-locks</code> failure in tag A does not affect tag B.</li><li>No global bottleneck.</li></ul><h3 id="who-writes-and-reads-yarilo-warden" tabindex="-1">Who writes and reads <code>yarilo-warden</code> <a class="header-anchor" href="#who-writes-and-reads-yarilo-warden" aria-label="Permalink to &quot;Who writes and reads `yarilo-warden`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Writer</th><th style="text-align:left;">What it writes</th></tr></thead><tbody><tr><td style="text-align:left;">director&#39;s login proxies (imap/pop3/submission)</td><td style="text-align:left;">CONNECT/DISCONNECT events (pre-auth connection tracking, per-IP rate limit)</td></tr><tr><td style="text-align:left;"><code>yarilo-lmtp-login</code></td><td style="text-align:left;">CONNECT/DISCONNECT per recipient (per-user delivery rate tracking)</td></tr><tr><td style="text-align:left;">backend&#39;s session processes (imap/pop3/submission)</td><td style="text-align:left;">SESSION_START / SESSION_END (post-auth, active mail sessions)</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Reader</th><th style="text-align:left;">When and why</th></tr></thead><tbody><tr><td style="text-align:left;">director&#39;s login proxies</td><td style="text-align:left;">Before admitting a new connection — enforce per-user/per-IP limits on connections + sessions</td></tr><tr><td style="text-align:left;"><code>yarilo-lmtp-login</code></td><td style="text-align:left;">Per RCPT TO — enforce per-user delivery concurrency limits before fan-out</td></tr></tbody></table><p>Warden merges conn-state (from the director / lmtp-login) with session-state (from the backends) — written from different processes, read from a single place (the login proxy).</p><h3 id="scaling-yarilo-warden" tabindex="-1">Scaling yarilo-warden <a class="header-anchor" href="#scaling-yarilo-warden" aria-label="Permalink to &quot;Scaling yarilo-warden&quot;">​</a></h3><p>Warden holds three pieces of shared state: the per-IP auth-failure <strong>penalty</strong> counter, the per-<code>user@ip</code> <strong>session</strong> accounting (the connection limit), and the <strong>kick bus</strong> (<code>EMIT</code>/<code>SUBSCRIBE</code>). Where that state lives is a single config choice:</p><h4 id="warden_service.state_backend" tabindex="-1"><code>state_<wbr>backend</code> <a class="header-anchor" href="#warden_service.state_backend" aria-label="Permalink to &quot;`state_backend` {#warden_service.state_backend}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>memory</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>memory</code> <code>redis</code></dd><dt>Helm</dt><dd><code>components.warden.service.state_backend</code></dd></dl></div><p>Where warden keeps its penalty counters, session accounting and kick bus. <code>memory</code> keeps them in the pod and allows one replica only; <code>redis</code> shares them and allows any number.</p><p>How the two values differ:</p><table tabindex="0"><thead><tr><th style="text-align:left;"><code>state_<wbr>backend</code></th><th style="text-align:left;">State lives in</th><th style="text-align:left;">Replicas</th><th style="text-align:left;">Deploy strategy</th></tr></thead><tbody><tr><td style="text-align:left;"><code>memory</code> (default)</td><td style="text-align:left;">the pod&#39;s process</td><td style="text-align:left;"><strong>must be 1</strong></td><td style="text-align:left;"><code>Recreate</code></td></tr><tr><td style="text-align:left;"><code>redis</code></td><td style="text-align:left;">shared Redis</td><td style="text-align:left;">any N</td><td style="text-align:left;"><code>RollingUpdate</code></td></tr></tbody></table><ul><li><strong><code>memory</code></strong> is the standalone / dev / test default. All three pieces of state are per-pod, so a second replica would see a <em>different</em> subset of sessions, enforce the limit independently, and — the decisive one — <strong>miss kicks</strong>: a login pod&#39;s <code>SUBSCRIBE</code> lands (via the ClusterIP) on one pod while an <code>EMIT</code> may land on another, and an in-process bus never crosses that gap. The chart therefore <strong>fails closed</strong> on <code>replicas &gt; 1</code> with <code>memory</code>, and the deploy strategy is <code>Recreate</code> so a rolling update never briefly runs two memory pods and splits their state.</li><li><strong><code>redis</code></strong> moves all three pieces into shared Redis: penalty is a key with TTL, sessions are hashes + an atomic counter reconciled by a sweep, and the kick bus is Redis <strong>Pub/Sub</strong> — an <code>EMIT</code> on any pod <code>PUBLISH</code>es, and every pod&#39;s subscribers receive it, so a kick published on pod-B is delivered by pod-A. Pods are then stateless and scale to any N behind the existing ClusterIP; the strategy is a normal <code>RollingUpdate</code>. This is the required setting before raising <code>replicas</code>.</li></ul><p>Both the subscribe path (go-redis auto-reconnects and re-subscribes on a Redis blip) and the login→warden transport (the login pod redials + re-subscribes) recover on their own, so a Redis or warden restart does not permanently deafen a pod to kicks. Kick delivery is best-effort / at-most-once and is <strong>not</strong> a correctness guarantee — the director&#39;s confirmed ring-wide kill holds <code>LOOKUP</code> until the ring-wide session count is stably zero, so split-writer safety never depends on a kick landing; the kick only makes teardown prompt.</p><p>Observability for the scale-out (all always-on, no debug flag): <code>yarilo_<wbr>warden_<wbr>connect_<wbr>total{result}</code>, <code>yarilo_<wbr>warden_<wbr>kick_<wbr>emitted_<wbr>total</code> / <code>yarilo_<wbr>warden_<wbr>kick_<wbr>delivered_<wbr>total</code> (different pods, proving cross-replica delivery under a scrape), <code>yarilo_<wbr>warden_<wbr>redis_<wbr>errors_<wbr>total{op}</code> (fail-open made visible), <code>yarilo_<wbr>warden_<wbr>reconcile_<wbr>adjustments_<wbr>total</code>, and <code>yarilo_<wbr>warden_<wbr>penalty_<wbr>updates_<wbr>total{result}</code>. Structured logs carry <code>pod=</code> so a kick can be traced across replicas directly.</p><hr><h2 id="write-locking" tabindex="-1">Write locking <a class="header-anchor" href="#write-locking" aria-label="Permalink to &quot;Write locking&quot;">​</a></h2><p><strong>Purpose:</strong> coordinate writes to mailbox and index files across the session processes (<code>yarilo-imap</code>, <code>yarilo-pop3</code>, <code>yarilo-submission</code>, <code>yarilo-lmtp</code>, <code>yarilo-managesieve</code>, <code>yarilo-jmap</code>) — uniformly across every deployment shape.</p><p><strong>Why needed:</strong> the session binaries live in distinct address spaces. In-process <code>sync.<wbr>Mutex</code> does not cross process boundaries. In backend deployments there is the additional dimension of coordination between StatefulSet replicas within the same tag (notably during failover).</p><h3 id="deployment-modes" tabindex="-1">Deployment modes <a class="header-anchor" href="#deployment-modes" aria-label="Permalink to &quot;Deployment modes&quot;">​</a></h3><p>A single <code>pkg/<wbr>locks</code> API and a single wire protocol, with two implementations behind it. <strong>Production k8s always uses remote mode</strong> (Redis-backed, mTLS TCP), regardless of how many replicas the deployment runs — this is the only mode that supports horizontal scaling without a config or code rework. Embedded mode is reserved for non-k8s use only.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Mode</th><th style="text-align:left;">Production k8s (standalone or backend)</th><th style="text-align:left;">Dev / CI</th></tr></thead><tbody><tr><td style="text-align:left;">When to use</td><td style="text-align:left;">Every k8s Helm release. Scales from 1 → N replicas via <code>replicaCount</code> in values.yaml.</td><td style="text-align:left;">Local CLI runs, unit tests, single-process smoke runs. <strong>Never in k8s.</strong></td></tr><tr><td style="text-align:left;">Process</td><td style="text-align:left;"><code>yarilo-locks</code> as its own Deployment (typically replicaCount=2 for HA).</td><td style="text-align:left;"><code>yarilo-locks --embedded</code> co-located in the same process tree.</td></tr><tr><td style="text-align:left;">State backend</td><td style="text-align:left;">Redis (bundled subchart or external).</td><td style="text-align:left;">In-memory map (ephemeral, pod-local).</td></tr><tr><td style="text-align:left;">Transport</td><td style="text-align:left;">mTLS TCP <code>:9104</code> reached through a ClusterIP Service.</td><td style="text-align:left;">Unix socket <code>/<wbr>run/<wbr>yarilo/<wbr>locks.<wbr>sock</code>.</td></tr><tr><td style="text-align:left;">HA</td><td style="text-align:left;">2+ replicas behind the Service; Redis HA via Sentinel/Cluster.</td><td style="text-align:left;">None — state dies with the process.</td></tr><tr><td style="text-align:left;">Scales to N session pods</td><td style="text-align:left;">Yes. All session pods reach the same locks Service and share state via Redis.</td><td style="text-align:left;">No. Unix socket is pod-local and in-memory state is per-process.</td></tr><tr><td style="text-align:left;">RTT (typical)</td><td style="text-align:left;">~1–2 ms (in-cluster Redis on the same node ~0.5 ms).</td><td style="text-align:left;">~100–300 µs.</td></tr><tr><td style="text-align:left;">Wire protocol</td><td style="text-align:left;">identical</td><td style="text-align:left;">identical</td></tr></tbody></table><p><strong>Why embedded is not a k8s option, even at <code>replicaCount=1</code>:</strong></p><ul><li>Unix-socket coordination is pod-local. Bump <code>replicaCount: 1 → 2</code> and the second pod cannot see lock state held by the first — two writers collide on the same NFS file.</li><li>A scheduled rolling restart of a single replica drops every in-flight lock. Remote mode survives this: clients reconnect to the surviving replica and pick up state from Redis.</li><li>Operator surprise is the worst kind of incident. The deployment must not silently switch semantics when the operator scales it up. One mode in production, end of story.</li></ul><p><strong>Two-tier locking convention:</strong> <code>sync.<wbr>Mutex</code> inside a process is the fast-path for goroutine-level contention (no RTT). <code>yarilo-locks</code> (always remote, in production) is engaged only when a cross-process barrier is required (any write to a shared file).</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Two independent sections in <code>yarilo.<wbr>yaml</code>. The yarilo-locks process consumes <code>locks_<wbr>service</code>; every session binary (yarilo-imap, yarilo-pop3, yarilo-submission, yarilo-lmtp, yarilo-managesieve, yarilo-jmap) consumes <code>locks_<wbr>client</code>. mTLS material is shared with the rest of the stack via <code>internal_<wbr>tls</code> — no separate keys live under the locks sections.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># k8s production (standalone or backend): yarilo-locks listens on TCP+mTLS,</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Redis backs the state.</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">locks_service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">remote</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  listen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:9104&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  redis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redis://redis.yarilo.svc.cluster.local:6379/0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  redis_password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${YARILO_REDIS_PASSWORD}&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # from a Secret, see below</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># session binaries reach yarilo-locks via the ClusterIP Service.</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">locks_client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">remote</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  endpoints</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;yarilo-locks.yarilo.svc.cluster.local:9104&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">internal_tls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/yarilo/tls/tls.crt</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/yarilo/tls/tls.key</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ca</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:   </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/yarilo/tls/ca.crt</span></span></code></pre></div><h4 id="locks_service.mode" tabindex="-1"><code>mode</code> <a class="header-anchor" href="#locks_service.mode" aria-label="Permalink to &quot;`mode` {#locks_service.mode}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>remote</code> <code>embedded</code></dd></dl></div><p><code>remote</code> serves locks over mTLS TCP with Redis behind it, and is the only mode for Kubernetes. <code>embedded</code> keeps them in memory behind a Unix socket, for tests and single-process runs.</p><h4 id="locks_service.listen" tabindex="-1"><code>listen</code> <a class="header-anchor" href="#locks_service.listen" aria-label="Permalink to &quot;`listen` {#locks_service.listen}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>components.locks.service.listen</code></dd></dl></div><p>Address yarilo-locks serves on in remote mode, <code>:9104</code> in the chart.</p><h4 id="locks_service.redis" tabindex="-1"><code>redis</code> <a class="header-anchor" href="#locks_service.redis" aria-label="Permalink to &quot;`redis` {#locks_service.redis}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd></dl></div><p>Redis URL that holds the lock state in remote mode. Leave the password out of the URL; the ConfigMap renders the URL as written.</p><h4 id="locks_service.socket" tabindex="-1"><code>socket</code> <a class="header-anchor" href="#locks_service.socket" aria-label="Permalink to &quot;`socket` {#locks_service.socket}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd></dl></div><p>Unix socket yarilo-locks serves on in embedded mode.</p><h4 id="locks_client.mode" tabindex="-1"><code>mode</code> <a class="header-anchor" href="#locks_client.mode" aria-label="Permalink to &quot;`mode` {#locks_client.mode}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>remote</code> <code>embedded</code></dd></dl></div><p>How a session process reaches yarilo-locks; matches the service&#39;s mode.</p><h4 id="locks_client.endpoints" tabindex="-1"><code>endpoints</code> <a class="header-anchor" href="#locks_client.endpoints" aria-label="Permalink to &quot;`endpoints` {#locks_client.endpoints}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd></dl></div><p>yarilo-locks addresses a session process dials in remote mode, normally the ClusterIP Service on <code>:9104</code>.</p><h4 id="locks_client.socket" tabindex="-1"><code>socket</code> <a class="header-anchor" href="#locks_client.socket" aria-label="Permalink to &quot;`socket` {#locks_client.socket}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd></dl></div><p>Unix socket a session process dials in embedded mode.</p><h4 id="redis-password" tabindex="-1">Redis password <a class="header-anchor" href="#redis-password" aria-label="Permalink to &quot;Redis password&quot;">​</a></h4><p>A Redis that requires a password gets it from a Secret, never from the ConfigMap. In the chart, <code>redis.<wbr>passwordSecret</code> (<code>name</code>, <code>key</code>, default <code>password</code>) puts it into the <code>YARILO_<wbr>REDIS_<wbr>PASSWORD</code> environment variable of every process that opens Redis: auth (session tokens), warden, locks, dict, quota-status, backend-api and the session containers. The bundled Redis then starts with <code>--requirepass</code> from the same Secret.</p><h5 id="redis.passwordSecret" tabindex="-1"><code>passwordSecret</code> <a class="header-anchor" href="#redis.passwordSecret" aria-label="Permalink to &quot;`passwordSecret` {#redis.passwordSecret}&quot;">​</a></h5><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>name: , key: password</code></dd><dt>Type</dt><dd>map</dd></dl></div><p>The Secret (<code>name</code>, <code>key</code>) whose value becomes <code>YARILO_<wbr>REDIS_<wbr>PASSWORD</code> in every process that opens Redis. The bundled Redis starts with the same password.</p><p>The config names the variable next to each Redis URL, and the loader expands it at startup:</p><h5 id="auth.token.redis_password" tabindex="-1"><code>redis_<wbr>password</code> <a class="header-anchor" href="#auth.token.redis_password" aria-label="Permalink to &quot;`redis_password` {#auth.token.redis_password}&quot;">​</a></h5><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd></dl></div><p>Password of the Redis that holds session tokens. Set it to <code>${YARILO_<wbr>REDIS_<wbr>PASSWORD}</code>; it wins over a password in the URL.</p><h5 id="warden_service.redis_password" tabindex="-1"><code>redis_<wbr>password</code> <a class="header-anchor" href="#warden_service.redis_password" aria-label="Permalink to &quot;`redis_password` {#warden_service.redis_password}&quot;">​</a></h5><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd></dl></div><p>Password of warden&#39;s Redis. Set it to <code>${YARILO_<wbr>REDIS_<wbr>PASSWORD}</code>; it wins over a password in the URL.</p><h5 id="locks_service.redis_password" tabindex="-1"><code>redis_<wbr>password</code> <a class="header-anchor" href="#locks_service.redis_password" aria-label="Permalink to &quot;`redis_password` {#locks_service.redis_password}&quot;">​</a></h5><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd></dl></div><p>Password of the Redis behind yarilo-locks. Set it to <code>${YARILO_<wbr>REDIS_<wbr>PASSWORD}</code>; it wins over a password in the URL.</p><p>The chart renders these three. A dict with <code>driver: redis</code> (quota clone, ACL owner registry, Sieve vacation and duplicate) is the operator&#39;s, so add <code>password: &quot;${YARILO_<wbr>REDIS_<wbr>PASSWORD}&quot;</code> to its <code>settings</code>. A separate password wins over one inside the URL. Do not put the password in the URL: the URL is rendered into the ConfigMap as written.</p><h4 id="server-name-of-internal-dials" tabindex="-1">Server name of internal dials <a class="header-anchor" href="#server-name-of-internal-dials" aria-label="Permalink to &quot;Server name of internal dials&quot;">​</a></h4><p>Every internal <strong>client</strong> dial (auth / warden / locks / backend-api / backend / fts / the login pods) verifies the peer against a single pinned name, <code>internal_<wbr>tls.<wbr>server_<wbr>name</code> — <strong>not</strong> the dialed host. Internal services are reached by short name, FQDN, or pod IP interchangeably, so host-based verification is unreliable; every internal certificate instead carries one stable SAN and every client pins it. Which component a peer <em>is</em> comes from its role, below.</p><p>The chart defaults <code>server_<wbr>name</code> to <code>&lt;release&gt;-internal</code> and puts that name in every certificate it makes; <strong>a certificate you provide MUST carry <code>&lt;release&gt;-internal</code> as a SAN</strong>. <code>internal_<wbr>tls.<wbr>enabled=true</code> with an empty <code>server_<wbr>name</code> fails <strong>loudly at startup</strong> (<code>mtls.<wbr>ClientConfig</code> errors with a fix hint) rather than as a cryptic &quot;ServerName must be specified&quot; on the first dial. <code>saslLogin</code> and <code>quotaStatus</code> now also carry an <code>internalTLS</code> block/mount — every component that dials an internal service needs the cert mounted.</p><h5 id="internal_tls.server_name" tabindex="-1"><code>server_<wbr>name</code> <a class="header-anchor" href="#internal_tls.server_name" aria-label="Permalink to &quot;`server_name` {#internal_tls.server_name}&quot;">​</a></h5><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>internalTLS.serverName</code></dd></dl></div><p>The one name every internal client verifies its peer against, instead of the host it dialed. The chart sets it to <code>&lt;release&gt;-internal</code> and puts it in every certificate it makes; a certificate you provide must carry it as a SAN. Empty with internal TLS on fails at startup.</p><p>The director <strong>ring</strong> dial is separate — see below.</p><h4 id="peer-roles" tabindex="-1">Peer roles <a class="header-anchor" href="#peer-roles" aria-label="Permalink to &quot;Peer roles&quot;">​</a></h4><p>Each internal certificate names the one component it speaks for in a DNS SAN <code>&lt;role&gt;.<wbr>role.<wbr>yarilo.<wbr>internal</code>, and each internal listener accepts only the roles that are meant to call it. <code>.<wbr>internal</code> is reserved for private use and never resolves publicly, so the name cannot collide with a service. Other DNS SANs are not identity.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Listener</th><th style="text-align:left;">Accepted roles</th></tr></thead><tbody><tr><td style="text-align:left;">auth client port</td><td style="text-align:left;">imap-login, pop3-login, submission-login, managesieve-login, jmap-login, sasl-login, imap, pop3, lmtp, managesieve, submission, admin</td></tr><tr><td style="text-align:left;">auth master port</td><td style="text-align:left;">imap, pop3, lmtp, managesieve, backend-api, fts, jmap, quota-status, lmtp-login, admin</td></tr><tr><td style="text-align:left;">warden</td><td style="text-align:left;">auth, imap-login, pop3-login, submission-login, managesieve-login, lmtp-login, jmap-login, backend-api, imap</td></tr><tr><td style="text-align:left;">locks</td><td style="text-align:left;">imap, pop3, lmtp, managesieve, backend-api, fts, jmap, admin</td></tr><tr><td style="text-align:left;">dict</td><td style="text-align:left;">imap, pop3, lmtp, managesieve</td></tr><tr><td style="text-align:left;">director</td><td style="text-align:left;">director (ring), the login roles and backend-api (LOOKUP), backend-reg (registration)</td></tr><tr><td style="text-align:left;">director admin API</td><td style="text-align:left;">admin, director-admin</td></tr><tr><td style="text-align:left;">backend-api</td><td style="text-align:left;">admin, backend-api</td></tr><tr><td style="text-align:left;">backend imap / pop3 / lmtp / managesieve / submission</td><td style="text-align:left;">the matching login: imap-login, pop3-login, lmtp-login, managesieve-login, submission-login</td></tr><tr><td style="text-align:left;">jmap internal</td><td style="text-align:left;">jmap-login</td></tr><tr><td style="text-align:left;">FTS</td><td style="text-align:left;">imap, pop3, lmtp, managesieve, backend-api, jmap</td></tr></tbody></table><p>The roles are <code>auth</code>, <code>warden</code>, <code>locks</code>, <code>dict</code>, <code>director</code>, <code>fts</code>, <code>backend-api</code>, <code>backend-reg</code>, <code>imap</code>, <code>pop3</code>, <code>lmtp</code>, <code>managesieve</code>, <code>submission</code>, <code>jmap</code>, <code>imap-login</code>, <code>pop3-login</code>, <code>submission-login</code>, <code>managesieve-login</code>, <code>lmtp-login</code>, <code>jmap-login</code>, <code>sasl-login</code>, <code>quota-status</code>, <code>admin</code> for the operator tools (yarctl, yarilo-migrate, the smoketest), and <code>director-admin</code>, the director pod&#39;s console, which reaches only the director admin API.</p><ul><li>A certificate with two role SANs, or a label outside this list, is refused.</li><li>The director also checks the role per command: ring commands only from <code>director</code>, registration only from <code>backend-reg</code>.</li><li>A refusal is logged with the peer certificate (subject, serial, role SANs), the listener and the roles it expected.</li><li><strong>This release accepts a certificate without a role</strong> and logs it once per listener and certificate, so a rolling upgrade from a shared certificate keeps internal connections up. The next release refuses it.</li><li>With <code>internal_<wbr>tls</code> off, each server logs once at startup that roles are not checked.</li><li>The FTS port and the director admin API are now behind internal mTLS as well. The admin API keeps its token.</li></ul><p><strong>On by default.</strong> Internal mTLS is one switch, <code>internalTLS.<wbr>enabled</code>, <code>true</code> by default. It drives the config, the mounts and the certificates of every component. The former <code>components.<wbr>&lt;name&gt;.<wbr>internalTLS.<wbr>enabled</code> flags are refused with a render error that names the switch: one of them could turn TLS on in the config of a component that got no certificate. Per-component <code>secretName</code> stays, for your own certificates. With the switch off, every internal port is plain and each server logs that roles are not checked.</p><h5 id="internal_tls.enabled" tabindex="-1"><code>enabled</code> <a class="header-anchor" href="#internal_tls.enabled" aria-label="Permalink to &quot;`enabled` {#internal_tls.enabled}&quot;">​</a></h5><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>internalTLS.enabled</code></dd></dl></div><p>Internal mTLS for every internal port. In the chart this one switch drives the config, the mounts and the certificates of every component. Off, every internal port is plain and each server logs that roles are not checked.</p><h5 id="internal_tls.cert" tabindex="-1"><code>cert</code> <a class="header-anchor" href="#internal_tls.cert" aria-label="Permalink to &quot;`cert` {#internal_tls.cert}&quot;">​</a></h5><div class="setting-card"><dl><dt>Default</dt><dd><code>/etc/yarilo/tls/tls.crt</code></dd><dt>Type</dt><dd>string</dd></dl></div><p>This component&#39;s certificate.</p><h5 id="internal_tls.key" tabindex="-1"><code>key</code> <a class="header-anchor" href="#internal_tls.key" aria-label="Permalink to &quot;`key` {#internal_tls.key}&quot;">​</a></h5><div class="setting-card"><dl><dt>Default</dt><dd><code>/etc/yarilo/tls/tls.key</code></dd><dt>Type</dt><dd>string</dd></dl></div><p>The private key of <code>cert</code>.</p><h5 id="internal_tls.ca" tabindex="-1"><code>ca</code> <a class="header-anchor" href="#internal_tls.ca" aria-label="Permalink to &quot;`ca` {#internal_tls.ca}&quot;">​</a></h5><div class="setting-card"><dl><dt>Default</dt><dd><code>/etc/yarilo/tls/ca.crt</code></dd><dt>Type</dt><dd>string</dd></dl></div><p>The CA every internal peer&#39;s certificate must chain to.</p><p><strong>Certificates from the chart.</strong> Every component without its own <code>secretName</code> gets <code>&lt;release&gt;-&lt;role&gt;-internal-tls</code>, made by the chart (<code>genSignedCert</code>, 10 years) and signed by:</p><ul><li><code>internalTLS.<wbr>ca.<wbr>secretName</code>, an existing <code>kubernetes.<wbr>io/<wbr>tls</code> Secret holding the CA certificate and key, for example the one cert-manager keeps for a CA Issuer. On a real install a missing Secret fails the render;</li><li>or, when that is empty, a CA the chart makes once and keeps in <code>&lt;release&gt;-internal-ca</code> (with <code>helm.<wbr>sh/<wbr>resource-policy: keep</code>).</li></ul><p>A certificate is kept from one upgrade to the next and re-issued only when its Secret is missing, the CA changed, or <code>internalTLS.<wbr>certGeneration</code> was raised. <strong>There is no renewal by age:</strong> a Helm template cannot read a certificate&#39;s expiry. For renewal over time use cert-manager.</p><p><strong>A plain <code>helm install</code> needs nothing else:</strong> with neither cert-manager nor <code>ca.<wbr>secretName</code>, the chart makes the CA once and every certificate from it.</p><p><strong>Limitation, GitOps renderers.</strong> The chart finds its existing Secrets with <code>lookup</code>, which sees the cluster only on <code>helm install</code> / <code>helm upgrade</code>. <code>helm template</code>, <code>--dry-run</code> and renderers such as Argo CD get no answers:</p><ul><li><strong>without <code>ca.<wbr>secretName</code></strong> they make a <strong>new CA</strong> on every render. Pods restarted after different syncs then trust different CAs, and internal links break. Such installs must set <code>internalTLS.<wbr>ca.<wbr>secretName</code> to a CA Secret made once outside the chart, or use <code>internalTLS.<wbr>certManager</code>;</li><li><strong>with <code>ca.<wbr>secretName</code></strong> the leaf certificates are still minted again on every render, but they all chain to the same CA, so links hold. The Secrets show a diff on every sync.</li></ul><p>The install notes (<code>NOTES.<wbr>txt</code>) repeat this when the chart makes its own CA.</p><h5 id="internalTLS.ca.secretName" tabindex="-1"><code>secretName</code> <a class="header-anchor" href="#internalTLS.ca.secretName" aria-label="Permalink to &quot;`secretName` {#internalTLS.ca.secretName}&quot;">​</a></h5><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd></dl></div><p>An existing <code>kubernetes.<wbr>io/<wbr>tls</code> Secret with the CA the chart signs internal certificates with. Empty, the chart makes a CA once and keeps it in <code>&lt;release&gt;-internal-ca</code>. A GitOps renderer must set it (or use cert-manager): without <code>lookup</code> it would make a new CA on every render.</p><h5 id="internalTLS.certGeneration" tabindex="-1"><code>certGeneration</code> <a class="header-anchor" href="#internalTLS.certGeneration" aria-label="Permalink to &quot;`certGeneration` {#internalTLS.certGeneration}&quot;">​</a></h5><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer</dd></dl></div><p>Raise it to re-issue every certificate the chart made. There is no renewal by age.</p><p><strong>Upgrading a release that ran with internal TLS off.</strong> Turning it on switches every internal link from plain to TLS at once. While the rollout runs, new pods speak TLS and old ones do not, so internal calls between old and new pods fail until the last pod has restarted. Plan the upgrade as a short outage, or set <code>internalTLS.<wbr>enabled: false</code> before upgrading and switch it on in a window of your choosing.</p><p><strong>cert-manager.</strong> With <code>internalTLS.<wbr>certManager.<wbr>enabled</code> and <code>internalTLS.<wbr>certManager.<wbr>issuerRef</code>, the chart renders one <code>Certificate</code> per role with the same DNS names, and cert-manager makes and renews the Secrets.</p><h5 id="internalTLS.certManager.enabled" tabindex="-1"><code>enabled</code> <a class="header-anchor" href="#internalTLS.certManager.enabled" aria-label="Permalink to &quot;`enabled` {#internalTLS.certManager.enabled}&quot;">​</a></h5><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>See also</dt><dd><a href="/main/installation/deployment.html#internalTLS.certManager.issuerRef"><code>issuerRef</code></a></dd></dl></div><p>Let cert-manager make and renew the internal certificates: one <code>Certificate</code> per role, with the same names.</p><h5 id="internalTLS.certManager.issuerRef" tabindex="-1"><code>issuerRef</code> <a class="header-anchor" href="#internalTLS.certManager.issuerRef" aria-label="Permalink to &quot;`issuerRef` {#internalTLS.certManager.issuerRef}&quot;">​</a></h5><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>kind: Issuer, name: </code></dd><dt>Type</dt><dd>map</dd><dt>See also</dt><dd><a href="/main/installation/deployment.html#internalTLS.certManager.enabled"><code>enabled</code></a></dd></dl></div><p>The cert-manager issuer that signs them.</p><p><strong>Your own certificates.</strong> Set <code>secretName</code> per component. Each certificate carries <code>&lt;role&gt;.<wbr>role.<wbr>yarilo.<wbr>internal</code> for that component, plus <code>&lt;release&gt;-internal</code>. The co-located backend pod mounts one Secret per container, so a single operator Secret there carries no role.</p><p><strong>yarctl</strong> presents the certificate the chart mounts at <code>/<wbr>etc/<wbr>yarilo/<wbr>admin-tls</code>:</p><ul><li><strong>backend-api containers:</strong> the <code>admin</code> certificate. yarctl there addresses the backend plane; <code>admin</code> is also accepted by the director admin API.</li><li><strong>director pod:</strong> the <code>director-admin</code> certificate, with <code>YARILO_<wbr>ADMIN_<wbr>TYPE=director</code>, its own API on <code>https:/<wbr>/<wbr>localhost</code> and the pinned name. Run director commands from there, for example <code>yarctl ring status</code>. A compromised director pod gains nothing it does not already hold (its API token and director certificate), and no path to mail.</li></ul><p>No other container holds either certificate.</p><h4 id="networkpolicy" tabindex="-1">NetworkPolicy <a class="header-anchor" href="#networkpolicy" aria-label="Permalink to &quot;NetworkPolicy&quot;">​</a></h4><p>With <code>networkPolicy.<wbr>enabled</code> (the default) the chart renders ingress policies that say on the network layer what the role matrix says in the handshake:</p><ul><li><strong>one per internal listener:</strong> the server pod admits on that port only the pods whose roles the listener accepts (the <a href="#peer-roles">peer roles</a> table). The co-located backend pod holds the imap, pop3, lmtp, managesieve, submission, jmap, fts, backend-api and backend-reg roles, so on the network it is one source, <code>backend</code>; the per-role split stays with mTLS. Traffic inside a pod is not policed;</li><li><strong>MTA-facing ports:</strong> lmtp-login, sasl-login and quota-status, from <code>networkPolicy.<wbr>mtaFrom</code>;</li><li><strong>telemetry and health</strong> (8080; 8080-8088 on the backend pod) of every pod a policy selects, from <code>networkPolicy.<wbr>telemetryFrom</code>.</li></ul><p>The client-facing login ports carry no policy and stay open. Egress is not restricted. The policies need a CNI that enforces them (Calico, Cilium, …).</p><h5 id="networkPolicy.enabled" tabindex="-1"><code>enabled</code> <a class="header-anchor" href="#networkPolicy.enabled" aria-label="Permalink to &quot;`enabled` {#networkPolicy.enabled}&quot;">​</a></h5><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd></dl></div><p>Render ingress policies that state on the network what the peer roles state in the handshake. They need a CNI that enforces them; egress is not restricted.</p><h5 id="networkPolicy.adminFrom" tabindex="-1"><code>adminFrom</code> <a class="header-anchor" href="#networkPolicy.adminFrom" aria-label="Permalink to &quot;`adminFrom` {#networkPolicy.adminFrom}&quot;">​</a></h5><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd></dl></div><p>Peers for operator tools outside the chart&#39;s pods (smoketest, yarilo-migrate) on the admin, auth and locks ports. Empty: <code>kubectl exec</code> into backend-api or the director.</p><h5 id="networkPolicy.mtaFrom" tabindex="-1"><code>mtaFrom</code> <a class="header-anchor" href="#networkPolicy.mtaFrom" aria-label="Permalink to &quot;`mtaFrom` {#networkPolicy.mtaFrom}&quot;">​</a></h5><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd></dl></div><p>Who may reach the MTA-facing ports. Empty is everyone.</p><h5 id="networkPolicy.telemetryFrom" tabindex="-1"><code>telemetryFrom</code> <a class="header-anchor" href="#networkPolicy.telemetryFrom" aria-label="Permalink to &quot;`telemetryFrom` {#networkPolicy.telemetryFrom}&quot;">​</a></h5><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd></dl></div><p>Who may reach telemetry and health. Empty is everyone. Kubelet probes come from the node and keep passing when it is narrowed.</p><p>Narrowing to a Postfix in a neighbouring namespace, and to Prometheus in <code>monitoring</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">networkPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mtaFrom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">namespaceSelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        matchLabels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kubernetes.io/metadata.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postfix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  telemetryFrom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">namespaceSelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        matchLabels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kubernetes.io/metadata.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">monitoring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  adminFrom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">podSelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        matchLabels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">job-name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">smoketest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h4 id="mta-facing-services-sasl-login-and-quota-status" tabindex="-1">MTA-facing services: sasl-login and quota-status <a class="header-anchor" href="#mta-facing-services-sasl-login-and-quota-status" aria-label="Permalink to &quot;MTA-facing services: sasl-login and quota-status&quot;">​</a></h4><p>Two services exist only for the MTA (Postfix), never for mail clients:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Service</th><th style="text-align:left;">Port</th><th style="text-align:left;">What it does</th></tr></thead><tbody><tr><td style="text-align:left;"><code>yarilo-sasl-login</code></td><td style="text-align:left;">12345</td><td style="text-align:left;">SASL authentication for Postfix (<code>smtpd_<wbr>sasl_<wbr>type = dovecot</code>): Postfix hands over the login and password a client sent, and gets yes or no</td></tr><tr><td style="text-align:left;"><code>yarilo-quota-status</code></td><td style="text-align:left;">12340</td><td style="text-align:left;">Postfix policy service: answers whether a message fits the recipient&#39;s quota</td></tr></tbody></table><p>Both answer to anyone who reaches them. sasl-login takes passwords in clear text and is a password oracle; quota-status tells which addresses exist and how full they are. Pick the variant that matches where the MTA runs.</p><p><strong>Postfix in the same cluster (recommended).</strong> Keep the chart default, <code>service.<wbr>type: ClusterIP</code>, so neither port leaves the cluster, and narrow <code>networkPolicy.<wbr>mtaFrom</code> to the MTA&#39;s namespace:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">networkPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mtaFrom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">namespaceSelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        matchLabels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kubernetes.io/metadata.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postfix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>smtpd_sasl_type = dovecot</span></span>\n<span class="line"><span>smtpd_sasl_path = inet:yarilo-sasl-login.&lt;namespace&gt;.svc:12345</span></span>\n<span class="line"><span>smtpd_recipient_restrictions = ..., check_policy_service inet:yarilo-quota-status.&lt;namespace&gt;.svc:12340</span></span></code></pre></div><p><strong>Postfix outside the cluster.</strong> Publish both with <code>service.<wbr>type: LoadBalancer</code>, as the production examples and the sandbox do, and restrict the sources on every layer that can:</p><ul><li><code>components.<wbr>saslLogin.<wbr>trusted_<wbr>nets</code>: the MTA&#39;s addresses; sasl-login refuses any other peer. Empty means everyone.</li><li><code>networkPolicy.<wbr>mtaFrom</code>: the same addresses as an <code>ipBlock</code>. This is the only in-chart restriction for quota-status, which has no <code>trusted_<wbr>nets</code>.</li><li>The load balancer: a source-range annotation of your provider, through <code>service.<wbr>annotations</code>, or an internal (non-public) load balancer. The chart renders no <code>loadBalancerSourceRanges</code>.</li><li>Keep the path off the public internet (an internal network or a VPN): passwords cross it in clear text.</li><li><code>components.<wbr>saslLogin.<wbr>haproxy</code> with <code>haproxy_<wbr>nets</code> when a proxy in front hides the MTA&#39;s address.</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  saslLogin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LoadBalancer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    trusted_nets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;203.0.113.10/32&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  quotaStatus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LoadBalancer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">networkPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mtaFrom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ipBlock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cidr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">203.0.113.10/32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h4 id="director-ring-tls" tabindex="-1">Director ring TLS <a class="header-anchor" href="#director-ring-tls" aria-label="Permalink to &quot;Director ring TLS&quot;">​</a></h4><p>The director dials its ring peers (JOIN, right-neighbor, seed polls) by <strong>ephemeral pod IP</strong>. Under <code>internal_<wbr>tls</code> the dial verifies the peer&#39;s certificate against <code>ring_<wbr>tls_<wbr>server_<wbr>name</code> (a stable name), <em>not</em> the pod IP — without it Go would check the pod IP against the cert&#39;s SANs and fail closed, so the ring would silently never converge. The dial uses a proper client config (with <code>RootCAs</code>); the ring <em>listener</em> keeps the mTLS server config.</p><p>The chart issues a <strong>director-specific</strong> internal-tls certificate (enable <code>components.<wbr>director.<wbr>internalTLS.<wbr>certificate</code>) whose SANs default to <code>&lt;release&gt;-director-ring</code> and <code>&lt;release&gt;-director</code>, and renders <code>ring_<wbr>tls_<wbr>server_<wbr>name</code> to <code>&lt;release&gt;-director-ring</code> automatically. The stock <em>shared</em> internal-tls secret has no such SAN — enabling <code>internal_<wbr>tls</code> on the director with that shared cert fails ring handshakes. On misconfiguration the director is loud: an <strong>ERROR</strong> when <code>internal_<wbr>tls</code> is on and peers are set but <code>ring_<wbr>tls_<wbr>server_<wbr>name</code> is empty, and a <strong>Warn</strong> when the configured name is absent from its own loaded certificate.</p><p><strong>Certificate rotation.</strong> cert-manager renews the Secret and kubelet refreshes the mounted files, but each director loads its <code>tls.<wbr>Config</code> <strong>once at startup</strong> — a renewed cert is picked up only after a <strong>rolling restart of the director Deployment</strong>. The ring survives a rolling restart normally: each director leaves gracefully before it stops.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># dev / unit tests / non-k8s CLI runs (single process, no Redis).</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">locks_service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">embedded</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  socket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/run/yarilo/locks.sock</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">locks_client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">embedded</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  socket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/run/yarilo/locks.sock</span></span></code></pre></div><h3 id="lock-model" tabindex="-1">Lock model <a class="header-anchor" href="#lock-model" aria-label="Permalink to &quot;Lock model&quot;">​</a></h3><ul><li><strong>Exclusive (X) locks</strong> for writes.</li><li><strong>Reads take no lock</strong> — the storage layer provides a consistent snapshot.</li><li>The protocol also offers shared locks and blocking variants (<code>LOCK-SHARED</code>, <code>LOCK-WAIT</code>, <code>LOCK-SHARED-WAIT</code>); the storage code takes only exclusive locks.</li><li>TTL-based: a lock releases itself if its holder crashes. The TTL and the renewal interval are chosen per kind of lock by the code that takes it; there is no single global value.</li><li>Granularity: per-mailbox (<code>mbox:&lt;user&gt;:&lt;folder&gt;</code>).</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Operation</th><th style="text-align:left;">Lock</th></tr></thead><tbody><tr><td style="text-align:left;">IMAP SELECT / FETCH / SEARCH / IDLE</td><td style="text-align:left;">none</td></tr><tr><td style="text-align:left;">LIST / LSUB</td><td style="text-align:left;">none</td></tr><tr><td style="text-align:left;">IMAP APPEND / EXPUNGE / STORE</td><td style="text-align:left;">X on mailbox</td></tr><tr><td style="text-align:left;">LMTP delivery</td><td style="text-align:left;">X on mailbox</td></tr><tr><td style="text-align:left;">Rename / Delete mailbox</td><td style="text-align:left;">X on mailbox</td></tr><tr><td style="text-align:left;">Sieve script update</td><td style="text-align:left;">X on user-scripts</td></tr></tbody></table><h3 id="wire-protocol" tabindex="-1">Wire protocol <a class="header-anchor" href="#wire-protocol" aria-label="Permalink to &quot;Wire protocol&quot;">​</a></h3><p>TAB-delimited, LF-terminated. In remote mode the transport is TCP over mTLS on port <code>:9104</code>. In embedded mode the identical byte stream runs over the Unix socket <code>/<wbr>run/<wbr>yarilo/<wbr>locks.<wbr>sock</code> (no TLS).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; VERSION\\t1\\n</span></span>\n<span class="line"><span>&lt; VERSION\\t1\\tOK\\n</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&gt; LOCK\\t&lt;resource&gt;\\t&lt;owner&gt;\\t&lt;ttl_ms&gt;[\\t&lt;site&gt;]\\n</span></span>\n<span class="line"><span>&lt; OK\\t&lt;lock_id&gt;\\n           # acquired</span></span>\n<span class="line"><span>&lt; BUSY\\t&lt;current_owner&gt;\\t&lt;site&gt;\\n   # held by someone else</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&gt; UNLOCK\\t&lt;lock_id&gt;\\n</span></span>\n<span class="line"><span>&lt; OK\\n | NOT_FOUND\\n</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&gt; RENEW\\t&lt;lock_id&gt;\\t&lt;new_ttl&gt;\\n</span></span>\n<span class="line"><span>&lt; OK\\n | EXPIRED\\n</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&gt; EMIT\\t&lt;resource&gt;\\t&lt;event_type&gt;\\t&lt;payload&gt;\\n</span></span>\n<span class="line"><span>&lt; OK\\n</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&gt; SUBSCRIBE\\t&lt;resource&gt;\\n</span></span>\n<span class="line"><span>&lt; EVENT\\t&lt;resource&gt;\\t&lt;event_type&gt;\\t&lt;payload&gt;\\n   # one line per EMIT on that resource</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&gt; COUNTER-INC\\t&lt;key&gt;\\t&lt;delta&gt;\\n</span></span>\n<span class="line"><span>&lt; OK\\t&lt;new_value&gt;\\n</span></span></code></pre></div><p><code>&lt;site&gt;</code> names the code path taking the lock, so a <code>BUSY</code> reply says who holds it and where. <code>LOCK-SHARED</code> takes the same arguments as <code>LOCK</code>.</p><p><code>LOCK-WAIT</code> and <code>LOCK-SHARED-WAIT</code> take one more, a wait limit: <code>LOCK-WAIT\\t&lt;resource&gt;\\t&lt;owner&gt;\\t&lt;ttl_<wbr>ms&gt;\\t&lt;site&gt;\\t&lt;wait_<wbr>ms&gt;</code>. Within that limit the caller waits in the server&#39;s queue — the order the backend keeps for every replica — and is answered <code>OK</code> once the lock is its own. When the limit runs out the answer is <code>BUSY</code> with the current owner and site. A malformed limit answers <code>ERROR bad_<wbr>wait</code>.</p><h3 id="what-stays-inside-the-session-processes" tabindex="-1">What stays inside the session processes <a class="header-anchor" href="#what-stays-inside-the-session-processes" aria-label="Permalink to &quot;What stays inside the session processes&quot;">​</a></h3><ul><li>Writing raw mail data (dbox segments, maildir files).</li><li>Writing index updates (under the X lock on the mailbox).</li><li>UID assignment (under the X lock — atomic read-increment-write of NEXTUID).</li><li>IDLE notifications published over the <code>yarilo-locks</code> EVENT channel.</li></ul><h3 id="deadlock-prevention" tabindex="-1">Deadlock prevention <a class="header-anchor" href="#deadlock-prevention" aria-label="Permalink to &quot;Deadlock prevention&quot;">​</a></h3><p>Code convention: always acquire locks in the order <code>idx:&lt;user&gt;</code> → <code>mbox:&lt;user&gt;:&lt;folder&gt;</code> → <code>deliver:&lt;user&gt;:&lt;folder&gt;</code>. If anything hangs, the TTL releases the lock automatically.</p><h3 id="storage-backend-remote-mode-only" tabindex="-1">Storage backend (remote mode only) <a class="header-anchor" href="#storage-backend-remote-mode-only" aria-label="Permalink to &quot;Storage backend (remote mode only)&quot;">​</a></h3><p>Redis (per backend deployment, or in the same namespace). Key: <code>lock:&lt;resource&gt;</code>, Value: <code>&lt;owner&gt;|&lt;acquired_<wbr>at&gt;</code>, TTL: the one the caller asked for. Atomic acquisition via Lua <code>SET .<wbr>.<wbr>.<wbr> NX EX</code>.</p><p>Embedded mode keeps the same key/value shape in a local <code>map[string]lockState</code> with a background TTL sweeper — no external dependencies.</p><h3 id="ha-remote-mode-only" tabindex="-1">HA (remote mode only) <a class="header-anchor" href="#ha-remote-mode-only" aria-label="Permalink to &quot;HA (remote mode only)&quot;">​</a></h3><ul><li>2 replicas of <code>yarilo-locks</code> per backend deployment, behind a ClusterIP Service.</li><li>Stateless (state in Redis).</li><li>Local Redis, or shared with other components (warden, etc.).</li></ul><p>Embedded mode has no HA — state is ephemeral; on process crash every lock is lost. Acceptable for unit tests and CLI dev runs; not used in k8s deployments.</p><h3 id="liveness-and-readiness" tabindex="-1">Liveness and readiness <a class="header-anchor" href="#liveness-and-readiness" aria-label="Permalink to &quot;Liveness and readiness&quot;">​</a></h3><p>The split, stated plainly so it is not &quot;completed&quot; back into a dependency probe:</p><ul><li><strong>liveness</strong> = <em>local process state</em>. It restarts a process that is up but whose own request path is wedged.</li><li><strong>readiness</strong> = <em>Redis reachability</em>. It removes a pod from rotation when its backend is unreachable, and returns it automatically once Redis answers.</li></ul><p><code>yarilo-locks</code> in <strong>remote mode deliberately wires no liveness self-check</strong>, because it has no local state that could wedge independently of Redis. The grant path is <code>handleLock → RedisBackend.<wbr>Acquire → Redis Lua script</code>, directly: <code>RedisBackend</code> holds no mutex, no queue, no in-process shard — the acquire <em>is</em> the Redis round-trip. The only in-process grant mutex is <code>MemoryBackend.<wbr>mu</code>, and that backend is used <strong>only</strong> in embedded/test mode, never in k8s. So the &quot;up but locally wedged&quot; state a liveness self-check exists to catch does not exist here — there is nothing between accept and the Redis call to deadlock.</p><p>A self-check that round-trips Redis is <strong>rejected</strong>: it re-creates the exact failure the watchdog guard-rail forbids. A hung Redis (TCP alive, no replies) would hang that probe on <strong>every</strong> locks replica at once, restarting the whole HA pool synchronously into a backoff loop — and a restart cannot fix a hung Redis. Both a down Redis and a hung Redis already have the correct answer: the readiness ping hangs or fails, the pod leaves rotation without a restart, and rejoins the moment Redis responds. Not-ready is the right degradation; dead is not.</p><p>The dead-accept-loop and hard-crash cases are covered by <code>os.<wbr>Exit(1)</code> on <code>Serve</code> error, no probe involved. So the coverage is complete without a locks watchdog: crash → <code>os.<wbr>Exit</code>; Redis unreachable/hung → readiness; and there is no third, local-only failure mode to add.</p><p><strong>Revisit trigger.</strong> If remote-mode <code>yarilo-locks</code> ever grows a genuine local stage in the grant path — an in-process cache, a grant queue, an in-process shard — this decision is reopened: that stage <em>can</em> wedge independently of Redis, and it should then get a liveness self-check that acquires and releases a <strong>probe-scoped</strong> lock through that stage, bounded by a timeout well above the worst-case acquire, and never reaching Redis. Until such a stage exists, there is nothing local to probe.</p><hr><h2 id="standalone-deployment" tabindex="-1">Standalone deployment <a class="header-anchor" href="#standalone-deployment" aria-label="Permalink to &quot;Standalone deployment&quot;">​</a></h2><p>The standalone deployment targets a single k8s node, no director, no per-tag sharding. It is <strong>built to scale from 1 → N replicas of each component by editing values.yaml</strong> — no rewiring, no protocol changes, no code touched. The same pattern carries the operator from a one-pod dev cluster to a small multi-replica production setup.</p><h3 id="docker-compose" tabindex="-1">Docker Compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to &quot;Docker Compose&quot;">​</a></h3><p>For local development, evaluation and small self-hosted installs there is a <strong>Docker Compose</strong> deployment (<a href="https://github.com/yarilomail/yarilo/tree/main/deploy/compose" target="_blank" rel="noreferrer">deploy/compose/</a>, <a href="/main/installation/docker_compose.html">Docker Compose</a>). It runs the standalone topology as one container per role — login proxies, session backends, <code>yarilo-auth</code>, <code>yarilo-warden</code>, <code>yarilo-locks</code> with Redis, <code>yarilo-fts</code> and <code>yarilo-backend-api</code> — on one host, with a SQLite userdb. It is a single-host target and is <strong>not</strong> highly available — for HA/scale-out use the Helm standalone or backend deployments above.</p><h3 id="components-all-as-k8s-deployments-unless-noted" tabindex="-1">Components (all as k8s Deployments unless noted) <a class="header-anchor" href="#components-all-as-k8s-deployments-unless-noted" aria-label="Permalink to &quot;Components (all as k8s Deployments unless noted)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Component</th><th style="text-align:left;">Default replicas</th><th style="text-align:left;">Scale by</th></tr></thead><tbody><tr><td style="text-align:left;"><code>yarilo-imap-login</code>, <code>yarilo-pop3-login</code>, <code>yarilo-submission-login</code></td><td style="text-align:left;">1 each</td><td style="text-align:left;"><code>replicaCount</code> per protocol (login is stateless beyond TLS state)</td></tr><tr><td style="text-align:left;"><code>yarilo-lmtp-login</code></td><td style="text-align:left;">0 (disabled by default)</td><td style="text-align:left;"><code>components.<wbr>lmtpLogin.<wbr>enabled: true</code> in values.yaml; MTA-facing LMTP proxy — warden CONNECT per recipient, SESSION token, preamble fan-out</td></tr><tr><td style="text-align:left;"><code>yarilo-jmap-login</code></td><td style="text-align:left;">1</td><td style="text-align:left;"><code>replicaCount</code> (stateless beyond TLS; scales on request load)</td></tr><tr><td style="text-align:left;"><code>yarilo-imap</code>, <code>yarilo-pop3</code>, <code>yarilo-submission</code>, <code>yarilo-lmtp</code>, <code>yarilo-jmap</code></td><td style="text-align:left;">1 each</td><td style="text-align:left;"><code>replicaCount</code> per protocol (coordination via locks)</td></tr><tr><td style="text-align:left;"><code>yarilo-auth</code></td><td style="text-align:left;">1</td><td style="text-align:left;"><code>replicaCount</code> (stateless; userdb in SQL)</td></tr><tr><td style="text-align:left;"><code>yarilo-warden</code></td><td style="text-align:left;">1</td><td style="text-align:left;">must stay 1 with <code>state_<wbr>backend: memory</code> (the default); any N with <code>state_<wbr>backend: redis</code></td></tr><tr><td style="text-align:left;"><code>yarilo-locks</code></td><td style="text-align:left;">2</td><td style="text-align:left;"><code>replicaCount</code> (state in Redis; 2 = HA default)</td></tr><tr><td style="text-align:left;"><code>redis</code></td><td style="text-align:left;">1 (StatefulSet)</td><td style="text-align:left;">external HA or Sentinel for production</td></tr></tbody></table><h3 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h3><p>A single <code>PersistentVolumeClaim</code> with <code>accessModes: [ReadWriteMany]</code> — every session pod mounts it at the same path. On single-node clusters this can be backed by <code>hostPath</code>, NFS, or a CSI RWX provisioner; on multi-node clusters it must be NFS or CephFS.</p><h3 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h3><p>A k8s <code>Service</code> per public port (993, 995, 465, 587, 143, 110, 8443) load-balances connections across the matching login pods. Port <code>24</code> is a <code>Service</code> in front of <code>yarilo-lmtp-login</code> (when enabled) which fans out per-recipient preamble connections to <code>yarilo-lmtp</code> backends. There is <strong>no director</strong> — sessions distribute round-robin (or by k8s <code>Service</code>&#39;s sessionAffinity setting). <code>yarilo-jmap-login</code> keeps its auth, warden and proxy duties here and simply skips the director lookup, addressing the <code>yarilo-jmap</code> Service directly; the binary is the same artefact as in the director-backed shape, the routing target comes from config. Cross-pod write contention is resolved through <code>yarilo-locks</code>; that adds RTT but stays correct. Once cross-pod contention is a measured problem, the upgrade path is a director deployment (separate document); the session and login binaries do not change.</p><h3 id="scale-invariants" tabindex="-1">Scale invariants <a class="header-anchor" href="#scale-invariants" aria-label="Permalink to &quot;Scale invariants&quot;">​</a></h3><ul><li><strong><code>yarilo-locks</code> is always remote mode</strong>, even at <code>replicaCount=1</code> for every other component. This is what keeps the deployment scalable without rework.</li><li><strong>All session processes call the locks Service via mTLS TCP.</strong> Storage code uses <code>pkg/<wbr>locks.<wbr>Locker</code> only; no compile-time switch on deployment shape.</li><li><strong>Storage is RWX from day one.</strong> Switching from RWO to RWX later requires a data migration and a full re-deploy. Doing it up front costs nothing extra.</li></ul><h3 id="out-of-scope-for-standalone" tabindex="-1">Out of scope for standalone <a class="header-anchor" href="#out-of-scope-for-standalone" aria-label="Permalink to &quot;Out of scope for standalone&quot;">​</a></h3><ul><li>Per-tag sharding (multiple NFS shares, different user populations on different backends). That belongs to the backend deployment (see <code>/<wbr>yarilo_<wbr>backend.<wbr>svg</code>).</li><li>Director-based sticky routing and consistent hashing. Standalone uses k8s <code>Service</code> load-balancing; if measured contention warrants it, switch to director without touching the session binaries.</li></ul><hr><h2 id="helm-chart-structure" tabindex="-1">Helm chart structure <a class="header-anchor" href="#helm-chart-structure" aria-label="Permalink to &quot;Helm chart structure&quot;">​</a></h2><p>There is one chart, <code>helm/</code>. Every component is switched on and sized under <code>components.<wbr>*</code> in <code>values.<wbr>yaml</code>; shared settings (TLS, Redis, telemetry) sit at the top level. A backend tag is the same chart installed once per tag, with <code>backend_<wbr>register.<wbr>tag</code> set to the tag and its own NFS PV.</p><h3 id="director-and-login-tier" tabindex="-1">Director and login tier <a class="header-anchor" href="#director-and-login-tier" aria-label="Permalink to &quot;Director and login tier&quot;">​</a></h3><ul><li><code>Deployment yarilo-director</code> — self-organizing ring: each replica dials only its right neighbor in <code>(ip, port)</code> sort order, never a full mesh, and every member count (including N=1, a lone replica) is a fully valid, service-serving state. Plain Deployment, not a StatefulSet — no per-pod stable network identity is needed. The headless <code>-director-ring</code> Service is the join seed: its DNS name resolves directly to every ready pod&#39;s IP, so any resolver hit lands on a live replica to <code>DIRECTOR-JOIN</code> against. The ClusterIP <code>-director</code> Service is what login pods send <code>LOOKUP</code> to.</li><li>One Deployment and Service per login proxy (<code>yarilo-imap-login</code>, <code>yarilo-pop3-login</code>, <code>yarilo-submission-login</code>, <code>yarilo-lmtp-login</code>, <code>yarilo-managesieve-login</code>, <code>yarilo-jmap-login</code>, <code>yarilo-sasl-login</code>). IMAP, POP3, Submission and JMAP default to LoadBalancer Services, the public entry points; <code>yarilo-managesieve-login</code> and <code>yarilo-lmtp-login</code> default to ClusterIP.</li></ul><h3 id="backend-per-tag" tabindex="-1">Backend (per tag) <a class="header-anchor" href="#backend-per-tag" aria-label="Permalink to &quot;Backend (per tag)&quot;">​</a></h3><p><strong>One co-located StatefulSet per tag</strong> — the pod runs every protocol container plus the sidecars:</p><ul><li><code>StatefulSet yarilo-backend</code> — <code>components.<wbr>backend.<wbr>replicas</code>. Pod containers: <code>yarilo-imap</code>, <code>yarilo-pop3</code>, <code>yarilo-submission</code>, <code>yarilo-lmtp</code>, <code>yarilo-managesieve</code>, <code>yarilo-jmap</code>, <code>yarilo-fts</code> (<code>fts_<wbr>addr = localhost</code>), <code>yarilo-backend-api</code> and <code>yarilo-backend-reg</code> (registration sidecar). All share the pod IP.</li><li><code>Deployment yarilo-locks</code> — cross-pod write coordination, state in Redis.</li><li><code>Deployment yarilo-quota-status</code> — global-read Postfix policy service, own replica count, stable ClusterIP for the external MTA (NOT in the pod; <code>backend-api</code> IS in the pod — see the co-location criterion above).</li><li>One <strong>PVC NFS (RWX)</strong> — shared by all pods within the tag.</li><li>One Headless Service — stable per-pod DNS.</li></ul><h3 id="shared-services" tabindex="-1">Shared services <a class="header-anchor" href="#shared-services" aria-label="Permalink to &quot;Shared services&quot;">​</a></h3><ul><li><code>Deployment yarilo-auth</code> — stateless (userdb in an external SQL/LDAP store).</li><li><code>Deployment yarilo-warden</code> — 1 replica with <code>state_<wbr>backend: memory</code>, any N with <code>redis</code>.</li><li>Redis (bundled or external) — state for warden, locks and session tokens, and redis dicts; its password comes from <code>redis.<wbr>passwordSecret</code>.</li></ul><p><strong>Why co-located, not per-protocol StatefulSets:</strong></p><ul><li><strong>Routing coherence (the whole point).</strong> Consistent hashing cannot give both &quot;1 user = 1 pod across protocols&quot; <em>and</em> independent per-protocol pod pools — they are mathematically incompatible. Separate pools would hash the same user to <em>different</em> pods for IMAP vs LMTP, so every cross-protocol write (LMTP delivery → the mailbox an IMAP session on another pod holds) crosses pods and fights over <code>yarilo-locks</code> / index-cache coherence. Co-locating restores the reference&#39;s one-mail-host invariant and makes the single ring + single userDir <strong>correct</strong>, not merely a shortcut.</li><li><strong>FTS single-writer for free.</strong> The per-user Xapian index has the same single-writer requirement as the mailbox. Co-locating <code>yarilo-fts</code> (localhost) puts the user&#39;s index write handle on their already-sticky pod, so each per-user index on the shared NFS has exactly one writer cluster-wide — no fts ring, no ClusterIP round-robin corruption. One invariant (&quot;1 user = 1 pod&quot;) covers the mailbox and the index together.</li><li><strong>One IP per user.</strong> The director stores one pod IP per user; that IP serves every protocol, so no protocol dimension is needed on the ring, the userDir, or the wire.</li><li>Vertical sizing stays per-protocol — each <strong>container</strong> keeps its own CPU/RAM limits. What is given up is <strong>independent per-protocol replica-count / HPA</strong>: you scale the pod (all protocols together), not one protocol&#39;s pool. This is a deliberate trade of an unused scaling axis for routing correctness.</li></ul><p><strong>Trade-off (documented, accepted):</strong> the whole pod scales as a unit, and one unready protocol container takes the pod (all protocols) out of the ring — see the readiness-gate semantics under &quot;backend liveness&quot;. Cross-protocol writes still go through <code>yarilo-locks</code> for cross-<em>pod</em> coordination (a user&#39;s replicas across the tag), but same-user same-protocol traffic is pinned to one pod.</p><h3 id="director-routing" tabindex="-1">Director routing <a class="header-anchor" href="#director-routing" aria-label="Permalink to &quot;Director routing&quot;">​</a></h3><p>The director maintains <strong>one</strong> consistent-hashing ring and <strong>one</strong> user→pod directory: <code>MD5(user) → yarilo-backend-&lt;tag&gt;-N</code> (the pod IP). The same pod answers IMAP, POP3, Submission and LMTP for that user; the login proxy dials the protocol-specific port on the resolved pod IP. <code>tag</code> selects the NFS shard, never the protocol. There is no per-protocol ring — a single user never lands on different pods for different protocols.</p><p><strong>Admin per-user ops reach the owning pod the same way.</strong> <code>yarilo-backend-api</code> listens on the pod IP only, so a per-user admin op (<code>yarctl backend fts rescan &lt;user&gt;</code>, folder/quota/index/… on a user) must hit the user&#39;s pod. <code>yarctl</code> does the routing <strong>client-side</strong>: it asks the director <code>GET /<wbr>api/<wbr>director/<wbr>map?user=X</code> — which resolves with the <em>same</em> precedence a login LOOKUP uses (sticky userDir pin → ring hash, the director owning the assignment) — then dials <code>http:/<wbr>/<wbr>{pod-ip}:{backend_<wbr>api_<wbr>port}</code>. It never picks a pod itself: a client-side choice would race a concurrent login and put two pods on one user&#39;s FTS index, breaking the single-writer invariant. Routing auto-enables when a director URL is configured (co-located); with no director it uses the fixed <code>--backend-url</code> (standalone). <code>--route-by-user=false</code> is a debug escape hatch for talking to one pod directly. If the director is unreachable the op fails with a clear error — never a silent fall-through to a random pod. Global ops (dict, user iterate) carry no user and always use the fixed URL.</p><hr><h2 id="where-the-chart-s-cpu-limits-come-from" tabindex="-1">Where the chart&#39;s CPU limits come from <a class="header-anchor" href="#where-the-chart-s-cpu-limits-come-from" aria-label="Permalink to &quot;Where the chart&#39;s CPU limits come from&quot;">​</a></h2><p><strong>Two of nineteen were measured. The rest are starting points.</strong></p><p>Every <code>limits.<wbr>cpu</code> in <code>helm/<wbr>values.<wbr>yaml</code> now says which it is, so the file can be read for what it knows rather than what it appears to advise:</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><code>fts</code> — <code>1</code></td><td style="text-align:left;">measured: one core saturates under sandbox delivery load, which is why <code>fts_<wbr>index_<wbr>workers</code> stays at 1</td></tr><tr><td style="text-align:left;"><code>jmap</code> — <code>500m</code></td><td style="text-align:left;">measured once and <strong>found short</strong>: 1.31 cores wanted under 8 clients and 50 users, with 81% of scheduling periods throttled</td></tr><tr><td style="text-align:left;">the other seventeen</td><td style="text-align:left;">unmeasured</td></tr></tbody></table><p>The numbers are not even uniform — <code>500m</code> for <code>director</code>, <code>pop3</code>, <code>lmtp</code>, <code>manageSieve</code> and <code>jmap</code>, <code>1000m</code> for <code>imap</code>, <code>200m</code> for most login layers — so there is no single policy behind them to reconstruct.</p><p><strong>What an unexplained limit costs.</strong> The first time anyone measured against one, JMAP read latency came out at a 5-second median and was investigated as an algorithmic defect twice, by two people, before the limit was found. A wrong limit does not fail; it produces numbers that look like a code problem.</p><p><strong>So measure under your own load before trusting any of them.</strong> The method is in <a href="/main/operations/testing.html#check-for-cpu-throttling-before-believing-a-latency-number">Testing</a>: run the matching job from <code>hack/<wbr>loadtest/</code>, read <code>cpu.<wbr>stat</code> inside the container, and establish the appetite with a second run at a different limit — one run only tells you the limit you chose, not where the workload stops asking.</p><p><strong>Throttling is invisible in yarilo&#39;s own <code>/<wbr>metrics</code>.</strong> It is a kubelet counter, <code>container_<wbr>cpu_<wbr>cfs_<wbr>throttled_<wbr>periods_<wbr>total</code>, exported through cAdvisor. Nothing scrapes it in the sandbox, so the reading has to be taken during a run or recorded with the result — after the fact, &quot;was it throttled yesterday&quot; has no answer.</p><p>The tables below are estimates from the same period as the defaults, and carry the same caveat.</p><h2 id="sizing-per-backend-pod" tabindex="-1">Sizing per backend pod <a class="header-anchor" href="#sizing-per-backend-pod" aria-label="Permalink to &quot;Sizing per backend pod&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Workload</th><th style="text-align:left;">RAM</th><th style="text-align:left;">CPU</th></tr></thead><tbody><tr><td style="text-align:left;">5k idle (mostly IMAP IDLE)</td><td style="text-align:left;">~300–500 MB</td><td style="text-align:left;">~0.1 cores</td></tr><tr><td style="text-align:left;">2k active</td><td style="text-align:left;">~500–800 MB</td><td style="text-align:left;">~0.3–0.5 cores</td></tr><tr><td style="text-align:left;">Burst (FETCH of a large mail × 100 users)</td><td style="text-align:left;">up to ~2 GB peak</td><td style="text-align:left;">up to 1–2 cores peak</td></tr></tbody></table><p><strong>Recommended Helm values:</strong></p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">resources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  requests</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">250m</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    memory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">512Mi</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  limits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000m</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    memory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2Gi</span></span></code></pre></div><p><strong>Bottlenecks (in order):</strong></p><ol><li><strong>Open FDs</strong> — <code>ulimit -n 65535</code> is required (default 1024 is too low). ~10 FD per session.</li><li><strong>NFS IOPS</strong> — the most likely bottleneck. SSD-backed NFS plus <code>cachefilesd</code>/<code>fscache</code> help.</li><li><strong>yarilo-locks RTT</strong> — every write does LOCK/UNLOCK. Local Redis → ~1–2 ms per pair.</li><li><strong>NFS bandwidth</strong> — attachment FETCH. 1 Gbps = 125 MB/s.</li><li><strong>RAM on burst</strong> — buffers for reading large mails.</li></ol><hr><h2 id="sizing-per-backend-tag-one-co-located-statefulset-one-nfs-share-local-locks" tabindex="-1">Sizing per backend tag (one co-located StatefulSet + one NFS share + local locks) <a class="header-anchor" href="#sizing-per-backend-tag-one-co-located-statefulset-one-nfs-share-local-locks" aria-label="Permalink to &quot;Sizing per backend tag (one co-located StatefulSet + one NFS share + local locks)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Parameter</th><th style="text-align:left;">Typical</th><th style="text-align:left;">Min/Max</th></tr></thead><tbody><tr><td style="text-align:left;">yarilo-backend replicaCount (co-located pod)</td><td style="text-align:left;">3–5</td><td style="text-align:left;">1 / scale-out</td></tr><tr><td style="text-align:left;">per-container resources (imap/pop3/submission/lmtp)</td><td style="text-align:left;">sized independently within the pod</td><td style="text-align:left;">see &quot;Sizing per backend pod&quot;</td></tr><tr><td style="text-align:left;">locks replicaCount</td><td style="text-align:left;"><strong>2</strong></td><td style="text-align:left;">stateless, ClusterIP</td></tr><tr><td style="text-align:left;">Users per pod</td><td style="text-align:left;"><strong>3–5k</strong> mostly idle</td><td style="text-align:left;">Goroutines are cheap, but FD/RAM limits apply</td></tr><tr><td style="text-align:left;"><strong>Total users per tag</strong></td><td style="text-align:left;"><strong>10–20k</strong></td><td style="text-align:left;">NFS server is the constraint</td></tr><tr><td style="text-align:left;">NFS share size</td><td style="text-align:left;"><strong>5–10 TB</strong></td><td style="text-align:left;">10k users × ~500 MB average quota</td></tr><tr><td style="text-align:left;">NFS sustained IOPS</td><td style="text-align:left;"><strong>10–30k</strong></td><td style="text-align:left;">Index/mailbox operations</td></tr><tr><td style="text-align:left;">NFS bandwidth</td><td style="text-align:left;"><strong>1–10 Gbps</strong></td><td style="text-align:left;">Attachment transfer</td></tr></tbody></table><hr><h2 id="when-to-create-a-new-tag" tabindex="-1">When to create a new tag <a class="header-anchor" href="#when-to-create-a-new-tag" aria-label="Permalink to &quot;When to create a new tag&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Trigger</th><th style="text-align:left;">Threshold</th></tr></thead><tbody><tr><td style="text-align:left;">NFS storage used</td><td style="text-align:left;">&gt; 70–75%</td></tr><tr><td style="text-align:left;">NFS sustained IOPS</td><td style="text-align:left;">&gt; 70% of capacity</td></tr><tr><td style="text-align:left;">Users per tag</td><td style="text-align:left;">&gt; 15–20k</td></tr><tr><td style="text-align:left;">p99 latency for simple IMAP ops</td><td style="text-align:left;">&gt; 200 ms</td></tr></tbody></table><p>One Helm release <code>yarilo-backend</code> per tag: <code>yarilo-backend-a</code>, <code>yarilo-backend-b</code>, … Each with its own NFS PV and its own <code>yarilo-locks</code> service.</p><p><strong>Scale examples:</strong></p><ul><li>10k users → 1 tag, 3 replicas, 5 TB NFS.</li><li>50k users → 3–4 tags, each with 3 replicas × 5 TB.</li><li>200k+ → 10–15 tags; start considering non-NFS storage.</li></ul><hr><h2 id="director-routing-stickiness" tabindex="-1">Director routing &amp; stickiness <a class="header-anchor" href="#director-routing-stickiness" aria-label="Permalink to &quot;Director routing &amp; stickiness&quot;">​</a></h2><p><strong>Ring:</strong> <code>MD5(username) → co-located backend pod</code> (within a single tag). One ring, one pod IP per user, serving every protocol — the login proxy dials the protocol-specific port on that IP. <strong>Tag assignment:</strong> a separate user → tag map (admin-defined or hash-based shard) — <code>tag</code> = NFS shard, not protocol.</p><ol><li>Client → login proxy (TLS terminate).</li><li>Login proxy: passdb through <code>yarilo-auth</code> (password + allow_nets).</li><li>Login proxy → director <code>LOOKUP &lt;user&gt; &lt;tag&gt;</code>; the director answers from the sticky assignment or the ring.</li><li>Login proxy dials the resolved pod IP on the protocol&#39;s port.</li><li>It sends the YARILO preamble with the auth state and pipes the session.</li></ol><p><code>userDir</code> in the director is an in-memory cache of active user → pod mappings. Synced between directors over the peer protocol.</p><hr><h2 id="ha-strategy" tabindex="-1">HA strategy <a class="header-anchor" href="#ha-strategy" aria-label="Permalink to &quot;HA strategy&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">HA approach</th></tr></thead><tbody><tr><td style="text-align:left;">Director</td><td style="text-align:left;">replicaCount=3, self-organizing ring</td></tr><tr><td style="text-align:left;">Backend per tag</td><td style="text-align:left;">replicaCount=3–5, shared NFS RWX, ring rebalance</td></tr><tr><td style="text-align:left;">yarilo-locks (per tag)</td><td style="text-align:left;">replicaCount=2, state in Redis</td></tr><tr><td style="text-align:left;">yarilo-auth</td><td style="text-align:left;">replicaCount=2, stateless</td></tr><tr><td style="text-align:left;">yarilo-warden</td><td style="text-align:left;"><code>state_<wbr>backend: redis</code>, then any replicaCount (1 with the default <code>memory</code>)</td></tr><tr><td style="text-align:left;">Redis</td><td style="text-align:left;">external HA (Sentinel/Cluster) or managed</td></tr><tr><td style="text-align:left;">NFS server</td><td style="text-align:left;">a separate HA effort (Pacemaker+DRBD, or managed NFS such as AWS EFS)</td></tr></tbody></table><p><strong>Backend failover sequence:</strong></p><ol><li>The pod stops heartbeating — the <code>yarilo-backend-reg</code> sidecar sends BACKEND-DOWN on SIGTERM (immediate); a hard kill or any unready protocol container → the sidecar goes silent → TTL expiry. Either way the <strong>whole pod</strong> leaves the ring for all protocols.</li><li>Every director removes it from the ring, together with the users and domains placed on it, and kicks its own login sessions that were proxied there.</li><li>Locks the dead pod held expire after their TTL on <code>yarilo-locks</code>.</li><li>Users move on their next login, to a live replica in the same tag: one pinned to the pod, or of a domain placed on it under <code>assignment_<wbr>policy: domain</code>, is placed afresh. Nothing is moved in a wave; a kicked session reconnects and is placed the same way.</li><li>The k8s scheduler brings up a new pod (~30 s).</li><li>The new pod mounts the same NFS and starts accepting connections.</li></ol><hr><h2 id="initial-placement-policy" tabindex="-1">Initial placement policy <a class="header-anchor" href="#initial-placement-policy" aria-label="Permalink to &quot;Initial placement policy&quot;">​</a></h2><h3 id="director_service.assignment_policy" tabindex="-1"><code>assignment_<wbr>policy</code> <a class="header-anchor" href="#director_service.assignment_policy" aria-label="Permalink to &quot;`assignment_policy` {#director_service.assignment_policy}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>hash</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>hash</code> <code>least_sessions</code> <code>domain</code></dd><dt>Helm</dt><dd><code>components.director.assignment_policy</code></dd></dl></div><p>How a user&#39;s first backend is chosen; sticky pins and moves do not consult it. The choices are described in <a href="#initial-placement-policy">Initial placement policy</a>.</p><p>Only the <strong>first</strong> (unpinned) user→backend assignment consults the policy; sticky pins and USER-MOVE are unaffected. The director is the <strong>single owner</strong> of placement — the LOOKUP path, LMTP <code>RouteUser</code>, and the admin per-user resolve all funnel through one <code>assignAndPin</code>, so no caller can independently pick a pod and split a user&#39;s per-user writer.</p><ul><li><p><strong><code>hash</code></strong> (default, the reference semantics): the consistent-hash backend for the user&#39;s tag. Deterministic — if a sticky entry expires after long inactivity the user returns to the same pod (warm per-user index locality on the shared PV, easy debugging).</p></li><li><p><strong><code>least_<wbr>sessions</code></strong>: the least-loaded Up backend in the tag by a two-level, capacity-normalized load — <strong>level 1</strong> the requesting protocol&#39;s sessions, <strong>level 2</strong> total sessions among level-1 ties; each <code>count*100/<wbr>vhosts</code> (<code>vhosts</code> 1..100; <strong><code>vhosts: 0</code> = drain → excluded</strong>); tie-break lower <code>(ip, port)</code>. Session counts come from the live SESSION-OPEN/CLOSE registry (no new plumbing), which now carries a trailing <code>proto</code> field on LOOKUP / SESSION-OPEN. The admin resolve has no protocol → level 1 is skipped, total load decides. Session counts are replicated ring-wide (SESSION-OPEN/CLOSE gossiped as (origin, seq) envelopes), so whichever random replica answers a LOOKUP decides on the full cluster view — not just the sessions on the watch-holding replica.</p></li><li><p><strong><code>domain</code></strong>: one backend per <strong>domain</strong>, chosen by load. A domain seen for the first time is placed on the Up backend of its tag with the fewest active connections and stays there; every later login of that domain follows it. This is what a shared mailbox needs — every member of a domain reaches the same backend — without pinning a whole domain by hash and hoping the distribution is even. A username with no domain falls back to the hash.</p><p>The placement is replicated across the director ring, so a director restart does not re-place a domain, and it is forgotten after <code>director_<wbr>domain_<wbr>expire</code> without a session.</p><p><strong>Load counted at placement, not at connect.</strong> The count a placement compares is the backend&#39;s active sessions <strong>plus the placements it has already been given whose sessions have not arrived yet</strong>. Without that, a burst of first logins across several new domains reads the same zeroes — SESSION-OPEN comes back after the LOOKUP that placed the user — and every one of them lands on one backend. (The reference raises its per-host count at assignment for the same reason.)</p><p><strong>Rebalance.</strong> When the busiest backend of a tag rises more than <code>director_<wbr>domain_<wbr>rebalance_<wbr>percent</code> above the quietest, one domain moves down — but only when the move actually narrows the spread, and among such moves the one that disconnects the fewest sessions. A move ends that domain&#39;s sessions on the backend it left, one user at a time through the confirmed kill.</p><p><strong>What it does not do.</strong> It does not split a domain: one large domain still fills the backend it was placed on, and the cure for that is spreading the domain across tags via userdb, exactly as with <code>%Ld</code>. It moves domains, not users.</p></li></ul><p><strong>Which one to use.</strong> <code>hash</code> where nothing is shared between users and determinism is worth more than balance. <code>least_<wbr>sessions</code> where users are independent and the load is uneven. <code>domain</code> where users of a domain share mailboxes or ACLs — it replaces the older <code>username_<wbr>hash: &quot;%Ld&quot;</code> + <code>assignment_<wbr>policy: hash</code> pairing, which achieves the same affinity but leaves the distribution to the hash.</p><p><strong>Trade-offs (least_sessions).</strong> It gives up hash determinism: an expired-then- returning user may land on a different pod than before. Acceptable because the data lives on the shared tag PV, but it must be a deliberate operator choice — hence the <code>hash</code> default. Second, because a fresh resolve now <strong>pins</strong>, a bulk admin sweep over never-logged-in users (e.g. <code>yarctl backend fts rescan</code> across a cohort) creates userDir entries for each — a deliberate side effect (the pins TTL-expire), so don&#39;t be surprised by a populated userDir after a mass operation. Reference parity: the reference does hash + vhosts weighting only; <code>least_<wbr>sessions</code> is a yarilo extension, default stays reference-compatible.</p><h3 id="domain-placement-settings" tabindex="-1">Domain placement settings <a class="header-anchor" href="#domain-placement-settings" aria-label="Permalink to &quot;Domain placement settings&quot;">​</a></h3><h4 id="director_service.director_domain_expire" tabindex="-1"><code>director_<wbr>domain_<wbr>expire</code> <a class="header-anchor" href="#director_service.director_domain_expire" aria-label="Permalink to &quot;`director_domain_expire` {#director_service.director_domain_expire}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>900</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.director_domain_expire</code></dd></dl></div><p>How long a domain placed by <code>assignment_<wbr>policy: domain</code> keeps its backend with no session. Separate from the user TTL so that a domain is not forgotten between two logins.</p><h4 id="director_service.director_domain_rebalance_percent" tabindex="-1"><code>director_<wbr>domain_<wbr>rebalance_<wbr>percent</code> <a class="header-anchor" href="#director_service.director_domain_rebalance_percent" aria-label="Permalink to &quot;`director_domain_rebalance_percent` {#director_service.director_domain_rebalance_percent}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>components.director.director_domain_rebalance_percent</code></dd><dt>See also</dt><dd><a href="/main/installation/deployment.html#director_service.director_domain_rebalance_interval"><code>director_domain_rebalance_interval</code></a> <a href="/main/installation/deployment.html#director_service.director_domain_rebalance_cooldown"><code>director_domain_rebalance_cooldown</code></a></dd></dl></div><p>Move one domain down when the busiest backend of a tag is this much above the quietest. <code>0</code> is off in the binary; the chart sets <code>20</code>, and a <code>0</code> in the values stays <code>0</code>.</p><h4 id="director_service.director_domain_rebalance_interval" tabindex="-1"><code>director_<wbr>domain_<wbr>rebalance_<wbr>interval</code> <a class="header-anchor" href="#director_service.director_domain_rebalance_interval" aria-label="Permalink to &quot;`director_domain_rebalance_interval` {#director_service.director_domain_rebalance_interval}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>60</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.director_domain_rebalance_interval</code></dd></dl></div><p>How often the rebalance is judged.</p><h4 id="director_service.director_domain_rebalance_cooldown" tabindex="-1"><code>director_<wbr>domain_<wbr>rebalance_<wbr>cooldown</code> <a class="header-anchor" href="#director_service.director_domain_rebalance_cooldown" aria-label="Permalink to &quot;`director_domain_rebalance_cooldown` {#director_service.director_domain_rebalance_cooldown}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>600</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.director_domain_rebalance_cooldown</code></dd></dl></div><p>How long a moved domain is left alone, so that two backends either side of the line do not trade it.</p><hr><h2 id="user-move-and-pin-longevity" tabindex="-1">USER-MOVE and pin longevity <a class="header-anchor" href="#user-move-and-pin-longevity" aria-label="Permalink to &quot;USER-MOVE and pin longevity&quot;">​</a></h2><p>An admin <strong>USER-MOVE</strong> (<code>yarctl director users move &lt;u&gt; --backend …</code>) is an <strong>operational tool — &quot;shift this user off that backend now&quot; — not permanent routing configuration.</strong> It writes a normal, TTL&#39;d userDir pin at the target (replicated ring-wide via the same <code>USER-MOVED</code> gossip) and immediately kicks the user&#39;s sessions on the old backend so the next connection lands on the new one. There is <strong>no permanent-override map</strong> and <strong>no USER-RELEASE</strong> — a move just expires.</p><p><strong>Longevity is session-driven, not permanent.</strong> While the user holds a live proxied session, the director keeps the pin&#39;s TTL fresh: every <code>user_<wbr>expire/<wbr>2</code> it touches the pin of every user with an active session in the replicated session registry. Each director refreshes from its own ring-replicated session view, so no extra propagation is needed. Once the user&#39;s <strong>last session closes</strong>, the touches stop and the pin <strong>lapses back to the ring hash</strong> after <code>user_<wbr>expire</code>. So a move survives exactly as long as the user stays connected; an idle user deterministically returns to their hash backend.</p><h3 id="director_service.user_expire" tabindex="-1"><code>user_<wbr>expire</code> <a class="header-anchor" href="#director_service.user_expire" aria-label="Permalink to &quot;`user_expire` {#director_service.user_expire}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>900</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.user_expire</code></dd></dl></div><p>How long a user&#39;s pin outlives their last session. While any session is open the pin is refreshed; after it, the user returns to their hash backend.</p><p>Operators who need a <strong>permanent</strong> placement should use <strong>tags</strong> (a user&#39;s tag-pool is routing configuration), not a move.</p><hr><h2 id="kick-pacing" tabindex="-1">Kick pacing <a class="header-anchor" href="#kick-pacing" aria-label="Permalink to &quot;Kick pacing&quot;">​</a></h2><p>Three settings shape how sessions are torn down. The last bounds a deliberate evacuation; see <a href="/main/architecture/director.html">Director</a>.</p><h3 id="director_service.user_kick_delay" tabindex="-1"><code>user_<wbr>kick_<wbr>delay</code> <a class="header-anchor" href="#director_service.user_kick_delay" aria-label="Permalink to &quot;`user_kick_delay` {#director_service.user_kick_delay}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>2</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.director.user_kick_delay</code></dd></dl></div><p>An admin kick, usually the tail of a move, waits this long so a command in flight on the old backend completes. A kick for a dead backend and a conflict kick never wait. <code>0</code> kicks at once.</p><h3 id="director_service.max_parallel_kicks" tabindex="-1"><code>max_<wbr>parallel_<wbr>kicks</code> <a class="header-anchor" href="#director_service.max_parallel_kicks" aria-label="Permalink to &quot;`max_parallel_kicks` {#director_service.max_parallel_kicks}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>100</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>components.director.max_parallel_kicks</code></dd></dl></div><p>When a backend goes down, its sessions are kicked in batches of this size, which spreads the re-logins over the surviving backends. <code>0</code> kicks all at once.</p><h3 id="director_service.max_parallel_moves" tabindex="-1"><code>max_<wbr>parallel_<wbr>moves</code> <a class="header-anchor" href="#director_service.max_parallel_moves" aria-label="Permalink to &quot;`max_parallel_moves` {#director_service.max_parallel_moves}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>5</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>components.director.max_parallel_moves</code></dd></dl></div><p>Confirmed kills in flight while <code>yarctl director backends flush</code> drains a backend.</p><hr><h2 id="stickiness-rationale" tabindex="-1">Stickiness rationale <a class="header-anchor" href="#stickiness-rationale" aria-label="Permalink to &quot;Stickiness rationale&quot;">​</a></h2><p>User X is always served by a single backend pod (within the same tag). Reasons:</p><ul><li>Less cross-pod lock contention in <code>yarilo-locks</code>.</li><li>Index cache locality.</li><li>Avoid duplicated IDLE notifications.</li><li>Faster session startup (cache prewarmed).</li></ul><p>Stickiness ≠ data partitioning. Data is shared on NFS; sticky routing is an optimisation.</p><hr><h2 id="why-event-loop-goroutines-not-fork" tabindex="-1">Why event-loop (goroutines), not fork <a class="header-anchor" href="#why-event-loop-goroutines-not-fork" aria-label="Permalink to &quot;Why event-loop (goroutines), not fork&quot;">​</a></h2><p>yarilo is written in Go. The Go runtime and <code>fork()</code> do not mix, so yarilo never forks.</p><ul><li><code>exec.<wbr>Command</code> — to launch child processes at pod startup.</li><li><strong>Goroutines per user</strong> within a process — one goroutine per user session.</li></ul><p>This is fundamentally different from a process-per-user model (fork per user → process per user → ~10 MB per session). yarilo holds 1000+ users in a single process without resource overhead.</p>',409)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
